import sys
import math
import random
from collections import deque, defaultdict
from heapq import heappush, heappop, heapify

def ria(n):
    return list(map(int, sys.stdin.readline().split()))

def rni():
    return int(sys.stdin.readline())

def ni():
    return int(input_tokens.popleft())

def rnl():
    return int(sys.stdin.readline())

def nl():
    return int(input_tokens.popleft())

def rline():
    return sys.stdin.readline().strip()

def prln(x):
    print(x)

def flush():
    pass

def close():
    pass

# Global input token buffer
input_tokens = deque()

def refill_tokens():
    global input_tokens
    line = sys.stdin.readline()
    if line:
        input_tokens = deque(line.strip().split())

# Read first line to initialize tokens
refill_tokens()

# Main logic
n = rni()
b = rni()
a = ria(n)
bal = [0] * n

for i in range(n):
    if i == 0:
        bal[i] = 1 if a[i] % 2 == 0 else -1
    else:
        bal[i] = bal[i - 1] + (1 if a[i] % 2 == 0 else -1)

pq = []
for i in range(1, n - 1):
    if bal[i] == 0:
        heappush(pq, abs(a[i + 1] - a[i]))

ans = 0
while pq and b >= pq[0]:
    b -= heappop(pq)
    ans += 1

prln(ans)
close()

