            int c = readByte();
            while (c <= ' ') c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int val = 0;
            do {
                val = val * 10 + c - '0';
                c = readByte();
            } while (c > ' ');
            return val * sign;
        }

        public long nextLong() {
            int c = readByte();
            while (c <= ' ') c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long val = 0;
            do {
                val = val * 10 + c - '0';
                c = readByte();
            } while (c > ' ');
            return val * sign;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = nextInt();
            return arr;
        }

        public String next() {
            int c = readByte();
            while (c <= ' ') c = readByte();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c > ' ');
            return sb.toString();
        }

        public String nextLine() {
            int c = readByte();
            while (c <= ' ') c = readByte();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c != '\n' && c != '\r' && c != -1);
            return sb.toString();
        }

        private boolean isWhitespace(int c) {
            return c <= ' ';
        }
    }

