        if self.numChars == -1:
            raise Exception("UnknownError")
        if self.curChar >= self.numChars:
            self.curChar = 0
            try:
                self.numChars = self.stream.readinto(self.buf)
            except Exception:
                raise Exception("UnknownError")
            if self.numChars <= 0:
                return -1
        result = self.buf[self.curChar]
        self.curChar += 1
        return result

    def peek(self):
        if self.numChars == -1:
            return -1
        if self.curChar >= self.numChars:
            self.curChar = 0
            try:
                self.numChars = self.stream.readinto(self.buf)
            except Exception:
                return -1
            if self.numChars <= 0:
                return -1
