            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (!isWhitespace(c)) {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        public long nextLong() throws IOException {
            int c;
            while (isWhitespace(c = read())) {}
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
