import java.io.*;
import java.util.*;

public class lets_do_variant5 {
    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader(System.in);
        int n = in.nextInt();
        int B = in.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = in.nextInt();

        int[] even = new int[n];
        int[] odd = new int[n];
        int ec = 0, oc = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] % 2 == 0) ec++;
            else oc++;
            even[i] = ec;
            odd[i] = oc;
        }

        List<Integer> diffs = new ArrayList<>();
        int prev = -1;

        for (int i = 1; i < n - 2; i += 2) {
            int ev = even[i] - (prev == -1 ? 0 : even[prev]);
            int od = odd[i] - (prev == -1 ? 0 : odd[prev]);
            if (ev == od) {
                diffs.add(Math.abs(arr[i + 1] - arr[i]));
            }
        }

        int m = diffs.size();
        int[] w = new int[m];
        int[] p = new int[m];
        for (int i = 0; i < m; i++) {
            w[i] = diffs.get(i);
            p[i] = 1;
        }

        int[][] dp = new int[m + 1][B + 1];
        for (int i = 1; i <= m; i++) {
            for (int cap = 0; cap <= B; cap++) {
                if (w[i - 1] <= cap) {
                    dp[i][cap] = Math.max(p[i - 1] + dp[i - 1][cap - w[i - 1]], dp[i - 1][cap]);
                } else {
                    dp[i][cap] = dp[i - 1][cap];
                }
            }
        }

        System.out.println(dp[m][B]);
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[8192];
        private int ptr = 0, len = 0;

        public InputReader(InputStream stream) {
            in = stream;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buf);
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() throws IOException {
            int c;
            while (isWhitespace(c = read())) {}
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (!isWhitespace(c)) {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        public long nextLong() throws IOException {
            int c;
            while (isWhitespace(c = read())) {}
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (!isWhitespace(c)) {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        public String next() throws IOException {
            int c;
            while (isWhitespace(c = read())) {}
            StringBuilder sb = new StringBuilder();
            while (!isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

