        int n = sc.nextInt();
        int B = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        int[] histogram = new int[101];
        int runningSum = 0;
        int selections = 0;

        for (int i = 0; i < n - 1; i++) {
            int evenCount = 0, oddCount = 0;
            for (int j = 0; j <= i; j++) {
                if (arr[j] % 2 == 0) evenCount++;
                else oddCount++;
            }

            if (evenCount == oddCount) {
                int diff = Math.abs(arr[i + 1] - arr[i]);
                int peak = findPeak(histogram);

                if (runningSum > B && diff < peak && peak != -1) {
                    runningSum -= peak;
                    histogram[peak]--;
                    histogram[diff]++;
                    runningSum += diff;
                } else if (runningSum < B) {
                    runningSum += diff;
                    histogram[diff]++;
                    selections++;
                }
            }
        }

        int idx = 100;
        while (runningSum > B && idx >= 0) {
            if (histogram[idx] > 0) {
                runningSum -= idx;
                selections--;
                histogram[idx]--;
            } else {
                idx--;
            }
        }

        System.out.println(selections);
    }

    private static int findPeak(int[] histogram) {
        for (int k = 100; k >= 0; k--) {
            if (histogram[k] > 0) return k;
        }
        return -1;
    }
}

