public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] nm = br.readLine().split("\\s+");
        int n = Integer.parseInt(nm[0]);
        int budget = Integer.parseInt(nm[1]);

        String[] line2 = br.readLine().split("\\s+");
        int[] values = new int[n];
        int[] balance = new int[n];
        int running = 0;

        for (int idx = 0; idx < n; idx++) {
            int val = Integer.parseInt(line2[idx]);
            values[idx] = val;
            running += (val % 2 == 0) ? 1 : -1;
            balance[idx] = running;
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 0; i < n - 1; i++) {
            if (balance[i] == 0) {
                pq.offer(Math.abs(values[i] - values[i + 1]));
            }
        }

        int totalSpent = 0;
        int cuts = 0;
        while (!pq.isEmpty() && totalSpent + pq.peek() <= budget) {
            totalSpent += pq.poll();
            cuts++;
        }

        System.out.print(cuts);
    }
}

