        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }

        List<Integer> diffs = new ArrayList<>();
        int even = 0, odd = 0;

        for (int i = 0; i < n - 1; i++) {
            if (a[i] % 2 == 0) even++;
            else odd++;

            if (even == odd) {
                diffs.add(Math.abs(a[i] - a[i + 1]));
            }
        }

        Collections.sort(diffs);

        int total = 0;
        int ans = 0;
        for (int d : diffs) {
            if (total + d > B) break;
            total += d;
            ans++;
        }

        out.println(ans);
        out.close();
        in.close();
    }

    static class InputReader implements Closeable {
        private final InputStream is;
        private final byte[] buf = new byte[1 << 16];
        private int ptr = 0, len = 0;

        public InputReader(InputStream is) {
            this.is = is;
        }

        private int read() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = is.read(buf);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }

        public int nextInt() {
            int c;
            while ((c = read()) <= 32 && c != -1) {}
            if (c == -1) throw new NoSuchElementException();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        @Override
        public void close() {
            try { is.close(); } catch (IOException ignored) {}
        }
    }
}

