import sys

class Reader:
    def __init__(self):
        self.BUFFER_SIZE = 1 << 16
        self.buffer = bytearray(self.BUFFER_SIZE)
        self.bufferPointer = 0
        self.bytesRead = 0
        self.stdin = sys.stdin.buffer

    def fillBuffer(self):
        self.bytesRead = self.stdin.readinto(self.buffer)
        if self.bytesRead == 0:
            self.buffer[0] = -1

    def read(self):
        if self.bufferPointer == self.bytesRead:
            self.fillBuffer()
        if self.bytesRead == 0:
            return -1
        byte_val = self.buffer[self.bufferPointer]
        self.bufferPointer += 1
        return byte_val

    def nextInt(self):
        ret = 0
        c = self.read()
        while c <= ord(' '):
            c = self.read()
        neg = False
        if c == ord('-'):
            neg = True
            c = self.read()
        while c >= ord('0') and c <= ord('9'):
            ret = ret * 10 + (c - ord('0'))
            c = self.read()
        if neg:
            return -ret
        return ret

