            if (r == 5) result += 4;
            return result;
        }

        if (min == 2) {
            if (max < 3) return 0;
            if (max == 3) return 4;
            if (max == 7) return 12;
            return min * max;
        }

        if (min == 3) {
            if (max < 3) return 0;
            long result = min * max;
            if (max % 2 == 1) result--;
            return result;
        }

        return 0;
    }
}

