class HopcroftKarpBipartiteMatching:
    def __init__(self, m, n, g):
        self.m = m
        self.n = n
        self.g = g
        self.pairU = [0] * (m + 1)
        self.pairV = [0] * (n + 1)
        self.dis = [0] * (m + 1)
        self.inf = 10000000
        self.NIL = 0

