        self.pairU = [0] * (self.m + 1)
        self.pairV = [0] * (self.n + 1)
        maxMatching = 0

        while self.bfs():
            for i in range(1, self.m + 1):
                if self.pairU[i] == 0 and self.dfs(i):
                    maxMatching += 1
        return maxMatching

    def bfs(self):
        q = deque()
        for i in range(1, self.m + 1):
            if self.pairU[i] == 0:
                q.append(i)
                self.dis[i] = 0
            else:
                self.dis[i] = self.inf
        self.dis[self.NIL] = self.inf

