import sys
from collections import deque

class FastScanner:
    def __init__(self, stream):
        self.stream = stream
        self.buffer = deque()

    def ns(self):
        while not self.buffer:
            line = self.stream.readline()
            if not line:
                return None
            self.buffer.extend(line.strip().split())
        return self.buffer.popleft()

    def ni(self):
        return int(self.ns())

class BDiv1:
