                nextOcc[depth] = (nextOcc[depth] + current) % MOD;
            }
            if (maxDepth + 1 <= n / 2) {
                nextOcc[maxDepth] = (nextOcc[maxDepth] + occ[maxDepth + 1]) % MOD;
