        final int MOD = 1_000_000_007;
        long sum = 0;

        // Use List-based structure for dynamic sizing
        List<List<Integer>> dp = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            dp.add(new ArrayList<>(Collections.nCopies(n + 1, 0)));
        }

        // Initialize first column
        for (int i = 0; i <= n; i++) {
            dp.get(i).set(0, 1);
            if (i % 2 == 1) {
                sum = (sum + 1) % MOD;
            }
        }

        // Fill DP table
        for (int j = 1; j <= n; j++) {
            for (int i = j; i <= n; i++) {
                int val = (dp.get(i).get(j - 1) + dp.get(i - 1).get(j)) % MOD;
                dp.get(i).set(j, val);
                if ((i + j) % 2 == 1) {
                    sum = (sum + val) % MOD;
                }
            }
        }

        System.out.println(sum);
    }
}

