public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (InputReader in = new InputReader(System.in);
             OutputWriter out = new OutputWriter(System.out)) {
            DNekoIPrank solver = new DNekoIPrank();
            solver.solve(1, in, out);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static class DNekoIPrank {
        private static final int MOD = 1_000_000_007;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            out.print(new Solve().compute(n));
        }

        class Solve {
            private int compute(int n) {
                int[][][] dp = new int[2 * n + 1][2 * n + 1][2];
                dp[0][0][0] = 1;

                for (int depth = 1; depth <= 2 * n; depth++) {
                    for (int opened = depth % 2; opened <= depth; opened += 2) {
                        if (opened > 0) {
                            dp[depth][opened][0] = (dp[depth][opened][0] + dp[depth - 1][opened - 1][1]) % MOD;
                            dp[depth][opened][1] = (dp[depth][opened][1] + dp[depth - 1][opened - 1][0]) % MOD;
                        }
                        if (opened < n) {
                            dp[depth][opened][0] = (dp[depth][opened][0] + dp[depth - 1][opened + 1][1]) % MOD;
                            dp[depth][opened][1] = (dp[depth][opened][1] + dp[depth - 1][opened + 1][0]) % MOD;
                        }
                        dp[depth][opened][0] = (dp[depth][opened][0] + 1) % MOD;
                    }
                }
                return dp[2 * n][0][1];
            }
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(int value) {
            writer.print(value);
        }

        public void close() {
            writer.close();
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int len = 0;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = stream.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int readInt() {
            int c = read();
            while (isSpace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (!isSpace(c)) {
                if (c < '0' || c > '9') throw new RuntimeException("Invalid input");
                val = val * 10 + c - '0';
                c = read();
            }
