        self.count = 0

    def read_byte(self):
        if self.count == -1:
            raise Exception("Input mismatch")
        if self.pos >= self.count:
            self.pos = 0
            try:
                self.count = self.in_stream.readinto(self.buf)
            except Exception:
                raise Exception("Input mismatch")
            if self.count <= 0:
                return -1
        val = self.buf[self.pos]
        self.pos += 1
        return val

    def next_int(self):
        c = self.read_byte()
        while c <= ord(' '):
            c = self.read_byte()
        sign = 1
        if c == ord('-'):
            sign = -1
            c = self.read_byte()
        val = 0
        while True:
            if c < ord('0') or c > ord('9'):
                raise Exception("Input mismatch")
            val = val * 10 + (c - ord('0'))
            c = self.read_byte()
            if c > ord(' '):
                break
        return val * sign


class OutputWriter:
    def __init__(self, stream):
        self.writer = open(stream.fileno(), 'w', closefd=False)

    def print(self, val):
        self.writer.write(str(val))

    def close(self):
        self.writer.flush()
        self.writer.close()


class Solver:
    MOD = 1000000007

    def solve(self, n):
        max_val = 2 * n + 1
        dp = [[[0] * 2 for _ in range(max_val)] for _ in range(max_val)]
        dp[0][0][0] = 1

        for d in range(1, 2 * n + 1):
            for o in range(d & 1, d + 1, 2):
                if o > 0:
                    dp[d][o][0] = (dp[d][o][0] + dp[d - 1][o - 1][1]) % self.MOD
                    dp[d][o][1] = (dp[d][o][1] + dp[d - 1][o - 1][0]) % self.MOD
                if o + 1 < max_val:
                    dp[d][o][0] = (dp[d][o][0] + dp[d - 1][o + 1][1]) % self.MOD
                    dp[d][o][1] = (dp[d][o][1] + dp[d - 1][o + 1][0]) % self.MOD
                dp[d][o][0] = (dp[d][o][0] + 1) % self.MOD
        return dp[2 * n][0][1]


class DNekoIPrank:
    def run(self, test_id, in_reader, out_writer):
        n = in_reader.next_int()
        out_writer.print(Solver().solve(n))


def main():
    app = Main()
    app.launch()


class Main:
    def launch(self):
        in_reader = InputReader(sys.stdin)
        out_writer = OutputWriter(sys.stdout)
        try:
            problem = DNekoIPrank()
            problem.run(1, in_reader, out_writer)
        finally:
            out_writer.close()


if __name__ == "__main__":
    main()

