        while (t-- > 0) {
            solve();
        }
        out.flush();
        out.close();
    }

    private static final int MOD = 1_000_000_007;

    private void solve() throws IOException {
        int n = scanner.nextInt();
        int[][] dp = new int[2 * n][n + 1];
        dp[0][1] = 1;

        for (int i = 1; i < 2 * n; i++) {
            for (int j = 0; j <= n; j++) {
                if (j + 1 <= n) {
                    dp[i][j + 1] = (dp[i][j + 1] + dp[i - 1][j]) % MOD;
