        long N = readLong(dis);
        long M = readLong(dis);
        long L = readLong(dis);
        long R = readLong(dis);

        long range = R - L + 1;
        long evenCount = range / 2;
        if (range % 2 == 1 && L % 2 == 0) evenCount++;
        long oddCount = range - evenCount;

        long totalCells = N * M;
        long answer;

        if (totalCells % 2 == 1) {
            answer = modPow(evenCount + oddCount, totalCells);
        } else {
            long t1 = modPow(evenCount + oddCount, totalCells);
            long t2 = modPow(evenCount - oddCount, totalCells);
            answer = (t1 + t2) % MOD;
            answer = (answer * modPow(2, MOD - 2)) % MOD;
        }

        out.println(answer);
        out.close();
    }

    private static long readLong(DataInputStream dis) throws IOException {
        long num = 0;
        int c;
        boolean neg = false;
        while ((c = dis.read()) <= ' ') {
            if (c == -1) return Long.MIN_VALUE;
        }
        if (c == '-') {
            neg = true;
            c = dis.read();
        }
        while (c > ' ') {
            num = (num << 3) + num + c - '0';
            c = dis.read();
        }
        return neg ? -num : num;
    }

    private static long modPow(long base, long exp) {
        base %= MOD;
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

