def fn(x, y, st, type_, dp):
    if dp[type_][st] != 0:
        return dp[type_][st]
    if st == 1:
        if type_ == 0:
            return x % mod
        return y % mod
    if st % 2 == 1:
        result = (x * fn(x, y, st - 1, type_, dp) + y * fn(x, y, st - 1, (type_ + 1) % 2, dp)) % mod
        dp[type_][st] = result
