        long n = Long.parseLong(tokens[0]);
        long m = Long.parseLong(tokens[1]);
        long p = Long.parseLong(tokens[2]);
        long q = Long.parseLong(tokens[3]);

        long range = q - p + 1;
        long oddCount, evenCount;
        if (p % 2 == 0) {
            evenCount = range - range / 2;
            oddCount = range / 2;
        } else {
            oddCount = range - range / 2;
            evenCount = range / 2;
        }

        Map<Long, Long>[] memoEven = new HashMap[2];
        Map<Long, Long>[] memoOdd = new HashMap[2];
        for (int i = 0; i < 2; i++) {
            memoEven[i] = new HashMap<>();
            memoOdd[i] = new HashMap<>();
        }

        if ((n & m) % 2 == 0) {
            long result = compute(evenCount, oddCount, n * m, 0, memoEven, memoOdd);
            System.out.println(result);
        } else {
            long total = evenCount + oddCount;
            long result = power(total, n * m, MOD);
            System.out.println(result);
        }
    }

