            if ((R - L) % 2 == 0) {
                result = (result + 1) % MOD;
            }
            long inv2 = modPow(2, MOD - 2, MOD);
            result = (result * inv2) % MOD;
            System.out.println(result);
        }
    }

    static long modPow(long base, long exp, long mod) {
        long res = 1;
        base = ((base % mod) + mod) % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

