import sys

class FastScanner:
    def __init__(self):
        self.in_stream = sys.stdin.buffer
        self.buffer = bytearray()
        self.ptr = 0
        self.buflen = 0

    def _fill_buffer(self):
        if self.ptr >= self.buflen:
            data = self.in_stream.read(1024)
            if not data:
                return False
            self.buffer = data
            self.buflen = len(data)
            self.ptr = 0
        return True

    def _has_next_byte(self):
        return self._fill_buffer() and self.ptr < self.buflen

    def _read_byte(self):
        if self._has_next_byte():
            b = self.buffer[self.ptr]
            self.ptr += 1
            return b
        return -1

    def _is_printable_char(self, c):
        return 33 <= c <= 126

    def _skip_unprintable(self):
        while self._has_next_byte() and not self._is_printable_char(self.buffer[self.ptr]):
            self.ptr += 1

    def _next(self):
        self._skip_unprintable()
        if not self._has_next_byte():
            raise StopIteration("No more input")
        sb = []
        b = self._read_byte()
        while self._is_printable_char(b):
            sb.append(chr(b))
            b = self._read_byte()
        return ''.join(sb)

    def next(self):
        return self._next()

    def nextLong(self):
        return int(self.next())

    def nextInt(self):
        return int(self.next())

    def nextDouble(self):
        return float(self.next())

