        b = self.buffer[self.ptr]
        self.ptr += 1
        while self._is_printable_char(b):
            sb.append(chr(b))
            b = self._read_byte()
            if b == -1:
                break

        return ''.join(sb)

    def next(self):
        return self._next()

    def nextInt(self):
        return int(self._next())

    def nextLong(self):
        return int(self._next())

    def nextDouble(self):
        return float(self._next())


