        if (wlen > 0) {
          if (open) {
            wc++;
          } else {
            if (wlen > max) max = wlen;
          }
          wlen = 0;
        }
      } else {
        wlen++;
      }
    }
    if (wlen > 0) {
      if (open) {
        wc++;
      } else {
        if (wlen > max) max = wlen;
      }
    }
    return max + " " + wc;
