def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    s = data[1].strip()

    winpars = 0
    longest = 0

    # Replace consecutive underscores with single underscore
    while "__" in s:
        s = s.replace("__", "_")
    n = len(s)

