        while j < n and s[j] != ')':
            j += 1
        if j < n and s[j] == ')':
            temp = s[i+1:j]
            if "_" not in temp and len(temp) > 0:
                winpars += 1
            else:
                tokens = temp.split('_')
                winpars += len([t for t in tokens if t])
            i = j
        i += 1

    # Second while loop for processing remaining parentheses
