public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }
    static class Solver {
        public void solve(Scanner in, PrintWriter out) {
            int n = in.nextInt();
            String s = in.next();
            int winpars = 0, longest = 0;
            int i = 0, j = 0;
            while (s.contains("__"))
                s = s.replaceAll("__", "_");
            n = s.length();
            // Process parentheses pairs
            for (int start = s.indexOf('('); start != -1; start = s.indexOf('(', start)) {
                int end = s.indexOf(')', start);
                if (end != -1) {
                    String inner = s.substring(start + 1, end);
                    if (!inner.contains("_") && !inner.isEmpty()) {
                        ++winpars;
                    } else {
                        StringTokenizer tok = new StringTokenizer(inner, "_");
                        winpars += tok.countTokens();
                    }
                    s = s.substring(0, start) + "_" + s.substring(end + 1);
                } else {
                    break;
                }
            }
            // Compute longest segment
            StringTokenizer tok = new StringTokenizer(s, "_");
            while (tok.hasMoreTokens()) {
                String part = tok.nextToken();
                if (part.length() > longest) {
                    longest = part.length();
                }
            }
            out.println(longest + " " + winpars);
        }
    }
}

