import sys
import re
from functools import reduce

class InputReader:
    def __init__(self, inputStream):
        self.reader = inputStream
        self.tokenizer = None

    def next(self):
        while self.tokenizer is None or not self.tokenizer:
            try:
                line = self.reader.readline()
                if not line:
                    return None
                self.tokenizer = line.strip().split()
            except Exception as e:
                print(e)
        return self.tokenizer.pop(0)

    def nextInt(self):
        return int(self.next())

def longestWords(line):
    if not line:
        return 0
    words = line.split('_')
    if not words:
        return 0
    return max(len(word) for word in words)

def trimParentheses(input_str):
    if len(input_str) < 2:
        return ""
    return input_str[1:-1]

def main():
    input_data = sys.stdin
    output = sys.stdout
    in_reader = InputReader(input_data)

    n = in_reader.nextInt()
    input_str = in_reader.next()

    pattern = r'\([\w_]*\)'
    outSite = re.split(pattern, input_str)
    longest = max((longestWords(s) for s in outSite), default=0)

    numberInside = 0
    matches = re.finditer(pattern, input_str)
    for match in matches:
        matched_group = match.group()
        trimmed = trimParentheses(matched_group)
        words = trimmed.split('_')
        non_empty_words = [word for word in words if word]
        numberInside += len(non_empty_words)

    output.write(f"{longest} {numberInside}\n")
    output.close()

if __name__ == "__main__":
    main()

