public class splitITup {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        String target = scan.next();

        List<Integer> parentStart = new ArrayList<>();
        List<Integer> parentEnd = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (target.charAt(i) == '(') {
                parentStart.add(i);
            }
            if (target.charAt(i) == ')') {
                parentEnd.add(i);
            }
        }

        int count = 0;
        for (int i = 0; i < parentEnd.size(); i++) {
            String s = target.substring(parentStart.get(i) + 1, parentEnd.get(i));
            String[] parts = s.split("_", -1);
            for (String part : parts) {
                if (!part.isEmpty()) {
                    count++;
                }
            }
        }

        int maxLen = 0;
        parentEnd.add(0, 0);
        parentStart.add(target.length());

        int startIdx = (target.charAt(0) == '(') ? 1 : 0;

        for (int i = startIdx; i < parentEnd.size(); i++) {
            int endPos = parentEnd.get(i);
            int startPos = parentStart.get(i);
            String s;
            if (target.charAt(endPos) == ')') {
                s = target.substring(endPos + 1, startPos);
            } else {
                s = target.substring(endPos, startPos);
            }

            String[] parts = s.split("_", -1);
            for (String part : parts) {
                if (part.length() > maxLen && !part.contains("(") && !part.contains(")")) {
                    maxLen = part.length();
                }
            }
        }

        System.out.println(maxLen + " " + count);
    }
}

