                if(S[i]=='_'){
                    if(par==0){
                        max_length = Math.max(max_length, count);
                    }
                    else if(count>0){
                        wordInPar++;
                    }
                    count=0;
                }
                else if(S[i]=='('){
                    par=1;
                    max_length = Math.max(max_length, count);
                    count=0;
                }
                else if(S[i]==')'){
                    par=0;
                    if(count>0){
                        wordInPar++;
                    }
                    count=0;
                }
                else{
                    count++;
                }
                if(par==0){
                    max_length = Math.max(max_length, count);
                }
            }

            out.println(max_length+" "+wordInPar);
        }

    }

