    void process() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        String s = in.next();

        int maxLen = 0;
        int start = 0;
        for (int i = 0; i <= s.length(); i++) {
            if (i == s.length() || s.charAt(i) == '(') {
                if (i > start) {
                    maxLen = Math.max(maxLen, computeMaxWord(s.substring(start, i)));
                }
                start = i;
            } else if (s.charAt(i) == ')') {
                start = i + 1;
            }
        }
        if (start < s.length()) {
            maxLen = Math.max(maxLen, computeMaxWord(s.substring(start)));
        }

        long insideCount = 0;
        int idx = 0;
        while ((idx = s.indexOf('(', idx)) != -1) {
            int end = s.indexOf(')', idx);
            if (end != -1) {
                String content = s.substring(idx + 1, end);
                if (!content.isEmpty()) {
                    insideCount += content.split("_", -1).length;
                }
                idx = end + 1;
            } else {
                break;
            }
        }

        out.println(maxLen + " " + insideCount);
        out.close();
    }

    int computeMaxWord(String str) {
        return Arrays.stream(str.split("_", -1))
                     .mapToInt(String::length)
                     .max()
                     .orElse(0);
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        InputReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

