import sys
import io

class B:
    def __init__(self):
        self.is_stdin = sys.stdin
        self.out = sys.stdout
        self.INPUT = ""
        self.oj = "ONLINE_JUDGE" in sys.platform or "ONLINE_JUDGE" in sys.argv or len(sys.argv) > 1 and sys.argv[1] == "oj"

    def solve(self):
        n = self.ni()
        s = list(self.ns())
        inner = False
        length = 0
        max1 = 0
        num2 = 0

        for c in s:
            if c == '_':
                if inner:
                    if length > 0:
                        num2 += 1
                else:
                    max1 = max(max1, length)
                length = 0
            elif c == '(':
                if inner:
                    if length > 0:
                        num2 += 1
                else:
                    max1 = max(max1, length)
                inner = True
                length = 0
            elif c == ')':
                if inner:
                    if length > 0:
                        num2 += 1
                else:
                    max1 = max(max1, length)
                inner = False
                length = 0
            else:
                length += 1

        if inner:
            if length > 0:
                num2 += 1
        else:
            max1 = max(max1, length)

        self.out.write(f"{max1} {num2}\n")

    def run(self):
        # For local testing, we can use a custom input
        if not self.oj and self.INPUT:
            self.is_stdin = io.StringIO(self.INPUT)

        self.solve()
        self.out.flush()

    def read_byte(self):
        c = self.is_stdin.read(1)
        if c == '':
            return -1
        return ord(c)

    def is_space_char(self, c):
        return not (33 <= c <= 126)

    def skip(self):
        b = self.read_byte()
        while b != -1 and self.is_space_char(b):
            b = self.read_byte()
        return b

    def ns(self):
        b = self.skip()
        sb = []
        while b != -1 and not self.is_space_char(b):
            sb.append(chr(b))
            b = self.read_byte()
        return ''.join(sb)

    def ni(self):
        num = 0
        b = self.skip()
        minus = False

        # Skip until we find a digit or '-'
        while b != -1 and not ((48 <= b <= 57) or b == 45):  # '0'-'9' or '-'
            b = self.read_byte()

        if b == 45:  # '-'
            minus = True
            b = self.read_byte()

        while True:
            if 48 <= b <= 57:  # '0'-'9'
                num = num * 10 + (b - 48)
            else:
                return -num if minus else num
            b = self.read_byte()

    def nl(self):
        num = 0
        b = self.skip()
        minus = False

        # Skip until we find a digit or '-'
        while b != -1 and not ((48 <= b <= 57) or b == 45):  # '0'-'9' or '-'
            b = self.read_byte()

        if b == 45:  # '-'
            minus = True
            b = self.read_byte()

        while True:
            if 48 <= b <= 57:  # '0'-'9'
                num = num * 10 + (b - 48)
            else:
                return -num if minus else num
            b = self.read_byte()

def main():
    solver = B()
    solver.run()

