public class codeforces {

    public static int findMaxConsecutiveNonSpecial(char[] arr, int start, int end) {
        int max = 0, current = 0;
        for (int i = start; i <= end; i++) {
            if (arr[i] != '_' && arr[i] != '(') {
                current++;
                max = Math.max(max, current);
            } else {
                current = 0;
            }
        }
        return max;
    }

    public static int countValidParentheses(char[] arr, int n) {
        int count = 0;
        int depth = 0;
        int lastStart = -1;

        for (int i = 0; i < n; i++) {
            if (arr[i] == '(') {
                depth++;
                lastStart = i;
            } else if (arr[i] == ')' && depth > 0) {
                depth--;
                if (depth == 0 && lastStart >= 0) {
                    int innerCount = 0;
                    for (int j = lastStart + 1; j < i; j++) {
                        if (arr[j] != '_' && arr[j] != '(') innerCount++;
                    }
                    if (innerCount > 0) count++;
