//				System.out.println(start+" "+s.charAt(i)+" "+max +" "+count+" ");
				if(s.charAt(i)=='_'){

					if(start!=i-1)
						if(in)
							count++;
						else
							max=Math.max(max, i-1-start);

					start=i;

				}

				if(s.charAt(i)=='('){
					in=true;
					if(start!=i-1)
						max=Math.max(max, i-1-start);

					start=i;
				}
				if(s.charAt(i)==')'){
					in=false;
					if(start!=i-1)
						count++;
					start=i;
				}
			}
			if(start!=s.length()-1)
				max=Math.max(max, s.length()-1-start);
			System.out.println(max+" "+count);

		out.flush();
		out.close();
	}

