import java.util.*;

public class Test {

	public static void main(String[] args) {
		ArrayList<String> arr1 = new ArrayList<>();
		ArrayList<String> arr2 = new ArrayList<>();
		Scanner in = new Scanner(System.in);
		int n, flag = 0;
		n = in.nextInt();
		String s = "", str = in.next();
		str += "^";
		n++;
		char[] input = new char[256];
		for (int i = 0; i < n; i++) {
			input[i] = str.charAt(i);
		}
		for (int i = 0; i < n; i++) {
			if (input[i] == '(') {
				flag = 1;
				input[i] = '^';
				continue;
			} else if (input[i] == ')') {
				flag = 0;
				arr2.add(s);
				input[i] = '^';
				s = "";
			}
			if (flag == 1) {
				s += input[i];
				input[i] = '^';
			}
		}
		s = "";
		for (int i = 0; i < n; i++) {
			if (input[i] == '^') {
				if (s.isEmpty() == true)
					continue;
				arr1.add(s);
				s = "";
			} else
				s += input[i];
		}
		int max = 0;
		int count = 0;
		for (int i = 0; i < arr1.size(); i++) {
			String temp = arr1.get(i);
			temp += "_";
			for (int j = 0; j < temp.length(); j++) {
				if (Character.isLetter(temp.charAt(j)) == true) {
					count++;
				} else if (temp.charAt(j) == '_') {
					max = Math.max(max, count);
					count = 0;
				}
			}
		}
		count = 0;
		for (int i = 0; i < arr2.size(); i++) {
			String temp = arr2.get(i);
			temp += "_";
			String m = "";
			for (int j = 0; j < temp.length(); j++) {
				if (Character.isLetter(temp.charAt(j)) == true) {
					m += temp.charAt(j);
				} else if (temp.charAt(j) == '_' && m.isEmpty() == false) {
					m = "";
					count++;
				}
			}
		}
		System.out.println(max + " " + count);
	}
}

