import sys
from collections import deque, defaultdict

MOD = 1000000007

class Pair:
    def __init__(self, d, w):
        self.d = d
        self.w = w

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = 0
    b = 0
    index = 2
    for i in range(n):
        if int(data[index]) == 50:
            a += 1
        else:
            b += 1
        index += 1

    # Precompute combinations (Pascal's triangle)
    choose = [[0] * 100 for _ in range(100)]
    for i in range(100):
        choose[i][0] = 1
    for i in range(1, 100):
        for j in range(1, i + 1):
            choose[i][j] = (choose[i-1][j-1] + choose[i-1][j]) % MOD

    # BFS setup
    startMask = 1000000 + 100 * a + b
    q = deque()
    q.append(startMask)
    ways = {startMask: Pair(0, 1)}

    while q:
        mask = q.popleft()
        boat = mask // 1000000
        nA = (mask % 1000000) // 100
        nB = mask % 100

        if boat > 0:  # Boat on left side, moving people from left to right
            for i in range(nA, -1, -1):
                if 50 * (nA - i) > k:
                    continue
                for j in range(nB, -1, -1):
                    if 50 * (nA - i) + 100 * (nB - j) > k:
                        continue
                    if i != nA or j != nB:
                        edgeWays = (choose[nA][i] * choose[nB][j]) % MOD
                        resolve(i, j, boat, mask, edgeWays, ways, q, a, b)
        else:  # Boat on right side, moving people from right to left
            for i in range(nA, a + 1):
                if 50 * (i - nA) > k:
                    continue
                for j in range(nB, b + 1):
                    if 50 * (i - nA) + 100 * (j - nB) > k:
                        continue
                    if i != nA or j != nB:
                        edgeWays = (choose[a - nA][i - nA] * choose[b - nB][j - nB]) % MOD
                        resolve(i, j, boat, mask, edgeWays, ways, q, a, b)

    if 0 in ways:
        print(ways[0].d)
        print(ways[0].w)
    else:
        print("-1")
        print("0")

def resolve(i, j, boat, mask, edgeWays, ways, q, a, b):
    newMask = 1000000 * (1 - boat) + i * 100 + j
    newD = ways[mask].d + 1

    if newMask not in ways:
        ways[newMask] = Pair(newD, 0)
        q.append(newMask)

    if ways[newMask].d == newD:
        ways[newMask].w = (ways[newMask].w + ways[mask].w * edgeWays) % MOD

if __name__ == "__main__":
