choose = [[0] * 100 for _ in range(100)]
queue = deque()
state_map = {}

class State:
    def __init__(self, depth, ways):
        self.depth = depth
        self.ways = ways

def encode_state(boat, a_count, b_count):
    return 1000000 * boat + 100 * a_count + b_count

def precompute_binomial_coefficients():
    for i in range(100):
        choose[i][0] = 1
    for i in range(1, 100):
        for j in range(1, i + 1):
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

def bfs(state):
    boat = state // 1000000
    curr_a = (state % 1000000) // 100
    curr_b = state % 100

    if boat == 1:
        for take_a in range(curr_a, -1, -1):
            if 50 * (curr_a - take_a) > k:
                continue
            for take_b in range(curr_b, -1, -1):
                if 50 * (curr_a - take_a) + 100 * (curr_b - take_b) > k:
                    continue
                if take_a != curr_a or take_b != curr_b:
                    ways = (choose[curr_a][take_a] * choose[curr_b][take_b]) % MOD
                    update_state(take_a, take_b, 0, state, ways)
    else:
        for take_a in range(curr_a, a + 1):
            if 50 * (take_a - curr_a) > k:
                continue
            for take_b in range(curr_b, b + 1):
                if 50 * (take_a - curr_a) + 100 * (take_b - curr_b) > k:
                    continue
                if take_a != curr_a or take_b != curr_b:
                    ways = (choose[a - curr_a][take_a - curr_a] * choose[b - curr_b][take_b - curr_b]) % MOD
                    update_state(take_a, take_b, 1, state, ways)

def update_state(new_a, new_b, new_boat, old_state, edge_ways):
    new_state = encode_state(new_boat, new_a, new_b)
    new_depth = state_map[old_state].depth + 1

    if new_state not in state_map:
        state_map[new_state] = State(new_depth, 0)
        queue.append(new_state)

    if state_map[new_state].depth == new_depth:
        current_ways = state_map[new_state].ways
        updated_ways = (current_ways + (state_map[old_state].ways * edge_ways) % MOD) % MOD
        state_map[new_state].ways = updated_ways

def main():
    global n, k, a, b
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx])
    idx += 1
    k = int(input_data[idx])
    idx += 1

    a = 0
    b = 0
    for _ in range(n):
        val = int(input_data[idx])
        idx += 1
        if val == 50:
            a += 1
        else:
            b += 1

    precompute_binomial_coefficients()
    start_state = encode_state(1, a, b)
    queue.append(start_state)
    state_map[start_state] = State(0, 1)

    while queue:
        bfs(queue.popleft())

    if 0 in state_map:
        final_state = state_map[0]
        print(f"{final_state.depth}\n{final_state.ways}")
    else:
        print("-1\n0")

if __name__ == "__main__":
    main()

