import java.io.*;
import java.util.*;

public class GregAndFriends {
    static int n, k, people50 = 0, people100 = 0;
    static final long MOD = 1000000007;
    static long[][] C = new long[100][100];
    static Queue<Integer> q = new ArrayDeque<>();
    static Map<Integer, Node> visited = new HashMap<>();

    static class Node {
        int dist;
        long cnt;

        Node(int d, long w) {
            dist = d;
            cnt = w;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        n = Integer.parseInt(firstLine[0]);
        k = Integer.parseInt(firstLine[1]);
        String[] weights = br.readLine().split(" ");
        for (String w : weights) {
            if (Integer.parseInt(w) == 50) people50++;
            else people100++;
        }
        br.close();

        buildCombinationTable();
        int initialState = encode(1, people50, people100);
        q.add(initialState);
        visited.put(initialState, new Node(0, 1));

        while (!q.isEmpty()) {
            processState(q.poll());
        }

        Node result = visited.get(0);
        if (result != null) {
            System.out.println(result.dist + "\n" + result.cnt);
        } else {
            System.out.println("-1\n0");
        }
    }

    static void processState(int state) {
        int boat = state / 1000000;
        int curr50 = (state % 1000000) / 100;
        int curr100 = state % 100;

        if (boat == 1) {
            for (int take50 = curr50; take50 >= 0 && 50 * (curr50 - take50) <= k; take50--) {
                for (int take100 = curr100; take100 >= 0 && 50 * (curr50 - take50) + 100 * (curr100 - take100) <= k; take100--) {
                    if (take50 != curr50 || take100 != curr100) {
                        long comb = (C[curr50][take50] * C[curr100][take100]) % MOD;
                        int nextBoat = 0;
                        int next50 = take50;
                        int next100 = take100;
                        updateState(nextBoat, next50, next100, state, comb);
                    }
                }
            }
        } else {
            for (int take50 = curr50; take50 <= people50 && 50 * (take50 - curr50) <= k; take50++) {
                for (int take100 = curr100; take100 <= people100 && 50 * (take50 - curr50) + 100 * (take100 - curr100) <= k; take100++) {
                    if (take50 != curr50 || take100 != curr100) {
                        long comb = (C[people50 - curr50][take50 - curr50] * C[people100 - curr100][take100 - curr100]) % MOD;
                        int nextBoat = 1;
                        int next50 = take50;
                        int next100 = take100;
                        updateState(nextBoat, next50, next100, state, comb);
                    }
                }
            }
        }
    }

    static void updateState(int boat, int a, int b, int prev, long comb) {
        int next = encode(boat, a, b);
        int newDist = visited.get(prev).dist + 1;

        if (!visited.containsKey(next)) {
            visited.put(next, new Node(newDist, 0));
            q.add(next);
        }

        if (visited.get(next).dist == newDist) {
            long newWays = (visited.get(next).cnt + visited.get(prev).cnt * comb % MOD) % MOD;
            visited.get(next).cnt = newWays;
        }
    }

    static void buildCombinationTable() {
        for (int i = 0; i < 100; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }
    }

    static int encode(int boat, int a, int b) {
        return 1000000 * boat + 100 * a + b;
    }
}

