import sys
from collections import deque

MOD = 1_000_000_007

def mod_pow(base, exponent):
    result = 1
    base %= MOD
    while exponent > 0:
        if exponent & 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exponent >>= 1
    return result

def mod_inverse(value):
    return mod_pow(value, MOD - 2)

def process():
    input_line = sys.stdin.readline().strip()
    while not input_line:
        input_line = sys.stdin.readline().strip()
    total_items = int(input_line)

    input_line = sys.stdin.readline().strip()
    while not input_line:
        input_line = sys.stdin.readline().strip()
    target_sum = int(input_line)

    factorial = [1] * 51
    for idx in range(1, 51):
        factorial[idx] = (factorial[idx - 1] * idx) % MOD

    binomial = [[0] * 51 for _ in range(51)]
    for row in range(51):
        binomial[row][0] = 1
        for col in range(1, row + 1):
            denominator = (factorial[col] * factorial[row - col]) % MOD
            binomial[row][col] = (factorial[row] * mod_inverse(denominator)) % MOD

    count_fifty = 0
    count_hundred = 0

    input_line = sys.stdin.readline().strip()
    while not input_line:
        input_line = sys.stdin.readline().strip()
    denominations = list(map(int, input_line.split()))

    for denom in denominations:
        if denom == 100:
            count_hundred += 1
        else:
            count_fifty += 1

    class State:
        def __init__(self, f, h, fl):
            self.fifty = f
            self.hundred = h
            self.flag = fl
            self.distance = 0
            self.paths = 0
            self.transitions = []

    graph = [[[State(0, 0, 0) for _ in range(2)] for _ in range(count_hundred + 1)] for _ in range(count_fifty + 1)]

    for f in range(count_fifty + 1):
        for h in range(count_hundred + 1):
            graph[f][h][0] = State(f, h, 0)
            graph[f][h][1] = State(f, h, 1)

    for f in range(count_fifty + 1):
        for h in range(count_hundred + 1):
            max_fifty = min(target_sum // 50, f)
            max_hundred = min(target_sum // 100, h)

            for h_use in range(max_hundred, -1, -1):
                remaining_sum = target_sum - (100 * h_use)
                max_fifty_use = min(max_fifty, remaining_sum // 50)

                for f_use in range(max_fifty_use, -1, -1):
                    if f_use == 0 and h_use == 0:
                        continue

                    src = graph[f][h][0]
                    dst = graph[f - f_use][h - h_use][1]

                    src.transitions.append(dst)
                    dst.transitions.append(src)

    queue = deque()
    graph[count_fifty][count_hundred][0].distance = 1
    graph[count_fifty][count_hundred][0].paths = 1
    queue.append(graph[count_fifty][count_hundred][0])

    while queue:
        current = queue.popleft()

        for next_state in current.transitions:
            if next_state.distance == 0 or next_state.distance == current.distance + 1:
                available_fifty = current.fifty if current.flag == 0 else count_fifty - current.fifty
                fifty_transition = abs(current.fifty - next_state.fifty)
                ways_fifty = binomial[available_fifty][fifty_transition]

                available_hundred = current.hundred if current.flag == 0 else count_hundred - current.hundred
                hundred_transition = abs(current.hundred - next_state.hundred)
                ways_hundred = binomial[available_hundred][hundred_transition]

                edge_ways = (ways_fifty * ways_hundred) % MOD
                next_state.paths = (next_state.paths + (current.paths * edge_ways) % MOD) % MOD

                if next_state.distance == 0:
                    next_state.distance = current.distance + 1
                    queue.append(next_state)

    final_node = graph[0][0][1]
    print(final_node.distance - 1)
    print(final_node.paths)

if __name__ == "__main__":
    process()

