class InputReader:
    def __init__(self, stream):
        self.in_stream = stream
        self.buffer = bytearray()
        self.index = 0
        self.size = 0

    def fetch(self):
        if self.size == -1:
            raise RuntimeError()
        if self.index >= self.size:
            self.index = 0
            try:
                self.size = self.in_stream.readinto(self.buffer)
            except Exception as e:
                raise RuntimeError() from e
            if self.size <= 0:
                return -1
        result = self.buffer[self.index]
        self.index += 1
        return result

