    }

    public int peek() {
        if (numChars == -1) return -1;
        if (curChar >= numChars) {
            curChar = 0;
            try { numChars = stream.read(buf); }
            catch (IOException e) { return -1; }
            if (numChars <= 0) return -1;
        }
        return buf[curChar];
    }

    public int readInt() {
        int c = read(); while (isSpaceChar(c)) c = read();
        int sgn = 1; if (c == '-') { sgn = -1; c = read(); }
        int res = 0;
        do { if (c < '0' || c > '9') throw new InputMismatchException(); res *= 10; res += c - '0'; c = read(); }
        while (!isSpaceChar(c));
        return res * sgn;
    }

    public long readLong() {
        int c = read(); while (isSpaceChar(c)) c = read();
        int sgn = 1; if (c == '-') { sgn = -1; c = read(); }
        long res = 0;
        do { if (c < '0' || c > '9') throw new InputMismatchException(); res *= 10; res += c - '0'; c = read(); }
        while (!isSpaceChar(c));
        return res * sgn;
    }

