import sys

class FastReader:
    def __init__(self):
        self.stdin = sys.stdin
        self.buffer = []
        self.index = 0

    def next(self):
        while self.index >= len(self.buffer):
            line = self.stdin.readline()
            if not line:
                return None
            self.buffer = line.split()
            self.index = 0
        result = self.buffer[self.index]
        self.index += 1
        return result

    def next_int(self):
        return int(self.next())

    def next_long(self):
        return int(self.next())

    def next_double(self):
        return float(self.next())

    def has_next(self):
        while self.index >= len(self.buffer):
            line = self.stdin.readline()
            if not line:
                return False
            self.buffer = line.split()
            self.index = 0
        return True

