    static long modBinomial(long n, long k, long p) {
        long numerator = 1;
        for (int i = 0; i < k; i++) {
            numerator = (numerator * (n - i)) % p;
        }
        long denominator = 1;
        for (int i = 1; i <= k; i++) {
            denominator = (denominator * i) % p;
        }
        return (numerator * modInverse(denominator, p)) % p;
