    for _ in range(n):
        arr.append(s.nextLong())
    return arr

def readInt():
    return s.nextInt()

def gcd(a, b):
    return a if b == 0 else gcd(b, a % b)

def binarySearch(lst, value, startIndex):
    left = startIndex
    right = len(lst) - 1
    result = len(lst)

    while left <= right:
        mid = (left + right) // 2
        if lst[mid] > value:
            if mid == 0 or lst[mid - 1] <= value:
                return mid
            right = mid - 1
        else:
            left = mid + 1
    return result

class Node:
    def __init__(self, ind, val):
        self.ind = ind
        self.val = val

def calculate(nodes, b, index):
    if index == 3:
        return 0

    current = nodes[index]
    otherIndex = (current.ind - 1 + 3) % 3

    transfer1 = min(current.val, b[otherIndex])
    current.val -= transfer1
    b[otherIndex] -= transfer1

    transfer2 = min(current.val, b[current.ind])
    current.val -= transfer2
    b[current.ind] -= transfer2

    total1 = current.val + calculate(nodes, b, index + 1)

    current.val += transfer1 + transfer2
    b[otherIndex] += transfer1
    b[current.ind] += transfer2

    current = nodes[index]
    transfer1 = min(current.val, b[current.ind])
    current.val -= transfer1
    b[current.ind] -= transfer1

    transfer2 = min(current.val, b[otherIndex])
    current.val -= transfer2
    b[otherIndex] -= transfer2

    total2 = current.val + calculate(nodes, b, index + 1)

    current.val += transfer1 + transfer2
    b[current.ind] += transfer1
    b[otherIndex] += transfer2

    return min(total1, total2)

