def process(items: List[Item], buffer: List[int], position: int) -> int:
    if position == 3:
        return 0

    current = items[position]
    alternate = (current.index + 2) % 3

    first_move = min(current.amount, buffer[alternate])
    current.amount -= first_move
    buffer[alternate] -= first_move

    second_move = min(current.amount, buffer[current.index])
    current.amount -= second_move
    buffer[current.index] -= second_move

    option1 = current.amount + process(items, buffer, position + 1)

    current.amount += first_move + second_move
    buffer[alternate] += first_move
    buffer[current.index] += second_move

    current = items[position]
