import sys
import math

class Reader:
    def __init__(self):
        self.buffer = sys.stdin
        self.tokens = []
        self.index = 0

    def fetch_token(self):
        while self.index >= len(self.tokens):
            line = self.buffer.readline()
            if not line:
                break
            self.tokens = line.strip().split()
            self.index = 0
            if len(self.tokens) == 0:
                continue
            break
        if self.index < len(self.tokens):
            token = self.tokens[self.index]
            self.index += 1
            return token
        return None

    def next_int(self):
        token = self.fetch_token()
        return int(token)

    def next_long(self):
        token = self.fetch_token()
        return int(token)

    def next(self):
        return self.fetch_token()

input_reader = Reader()

def read_longs(count):
    values = []
    for _ in range(count):
        values.append(input_reader.next_long())
    return values

def read_int():
    return input_reader.next_int()

def gcd(x, y):
    return x if y == 0 else gcd(y, x % y)

def locate(sorted_list, value, begin):
    left = begin
    right = len(sorted_list) - 1
    answer = len(sorted_list)

    while left <= right:
        middle = (left + right) // 2
        if sorted_list[middle] > value:
            if middle == 0 or sorted_list[middle - 1] <= value:
                return middle
            right = middle - 1
        else:
            left = middle + 1
    return answer

def evaluate(containers, storage, step):
    if step == 3:
        return 0

    current = containers[step]
    other = (current['position'] + 2) % 3

    first_transfer = min(current['quantity'], storage[other])
    current['quantity'] -= first_transfer
    storage[other] -= first_transfer

    second_transfer = min(current['quantity'], storage[current['position']])
    current['quantity'] -= second_transfer
    storage[current['position']] -= second_transfer

    first_result = current['quantity'] + evaluate(containers, storage, step + 1)

    current['quantity'] += first_transfer + second_transfer
    storage[other] += first_transfer
    storage[current['position']] += second_transfer

    current = containers[step]
    first_transfer = min(current['quantity'], storage[current['position']])
    current['quantity'] -= first_transfer
    storage[current['position']] -= first_transfer

    second_transfer = min(current['quantity'], storage[other])
    current['quantity'] -= second_transfer
    storage[other] -= second_transfer

    second_result = current['quantity'] + evaluate(containers, storage, step + 1)

    current['quantity'] += first_transfer + second_transfer
    storage[current['position']] += first_transfer
    storage[other] += second_transfer

    return min(first_result, second_result)

def main():
    result = []
    cases = 1
    for _ in range(cases):
        n = read_int()
        first = read_longs(3)
        second = read_longs(3)

        upper = min(first[0], second[1]) + min(first[1], second[2]) + min(first[2], second[0])
        lower = max(0, first[0] + second[1] - n) + max(0, first[1] + second[2] - n) + max(0, first[2] + second[0] - n)
        result.append(f"{lower} {upper}")

    print("\n".join(result))

if __name__ == "__main__":
    main()

import sys
import io

class Scanner:
    def __init__(self):
        self.reader = io.BufferedReader(io.BytesIO(sys.stdin.buffer.read())) if sys.stdin.buffer else io.BufferedReader(sys.stdin)
        self.buffer = []
        self.pos = 0

    def refill(self):
        if self.pos >= len(self.buffer):
            line = self.reader.readline().decode('utf-8').strip()
            if not line:
                return
            self.buffer = line.split()
            self.pos = 0

    def next(self):
        self.refill()
        if self.pos < len(self.buffer):
            result = self.buffer[self.pos]
            self.pos += 1
            return result
        return None

    def nextInt(self):
        return int(self.next())

    def nextLong(self):
        return int(self.next())

scanner = Scanner()
printer = sys.stdout

def readArray(length):
    arr = []
    for _ in range(length):
        arr.append(scanner.nextLong())
    return arr

def readInt():
    return scanner.nextInt()

def gcd(a, b):
    return a if b == 0 else gcd(b, a % b)

def binarySearch(lst, value, start):
    left = start
    right = len(lst) - 1
    result = len(lst)

    while left <= right:
        mid = (left + right) // 2
        if lst[mid] > value:
            if mid == 0 or lst[mid - 1] <= value:
                return mid
            right = mid - 1
        else:
            left = mid + 1
    return result

def compute(storages, buffer, index):
    if index == 3:
        return 0

    current = storages[index]
    other = (current['idx'] + 2) % 3

    xfer1 = min(current['val'], buffer[other])
    current['val'] -= xfer1
    buffer[other] -= xfer1

    xfer2 = min(current['val'], buffer[current['idx']])
    current['val'] -= xfer2
    buffer[current['idx']] -= xfer2

    option1 = current['val'] + compute(storages, buffer, index + 1)

    current['val'] += xfer1 + xfer2
    buffer[other] += xfer1
    buffer[current['idx']] += xfer2

    current = storages[index]
    xfer1 = min(current['val'], buffer[current['idx']])
    current['val'] -= xfer1
    buffer[current['idx']] -= xfer1

    xfer2 = min(current['val'], buffer[other])
    current['val'] -= xfer2
    buffer[other] -= xfer2

    option2 = current['val'] + compute(storages, buffer, index + 1)

    current['val'] += xfer1 + xfer2
    buffer[current['idx']] += xfer1
    buffer[other] += xfer2

    return min(option1, option2)

def main():
    t = 1
    output_lines = []
    for _ in range(t):
        n = readInt()
