    return arr

def read_int():
    return input.next_int()

def gcd(x, y):
    return x if y == 0 else gcd(y, x % y)

def find_index(lst, val, start):
    lo = start
    hi = len(lst) - 1
    ans = len(lst)

    while lo <= hi:
        mid = (lo + hi) // 2
        if lst[mid] > val:
            if mid == 0 or lst[mid - 1] <= val:
                return mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

class Slot:
    def __init__(self, pos, val):
        self.pos = pos
        self.val = val

def solve(slots, buffer, pos):
    if pos == 3:
        return 0

    cur = slots[pos]
    alt = (cur.pos + 2) % 3

    t1 = min(cur.val, buffer[alt])
    cur.val -= t1
    buffer[alt] -= t1

    t2 = min(cur.val, buffer[cur.pos])
    cur.val -= t2
    buffer[cur.pos] -= t2

    res1 = cur.val + solve(slots, buffer, pos + 1)

    cur.val += t1 + t2
    buffer[alt] += t1
    buffer[cur.pos] += t2

    cur = slots[pos]
    t1 = min(cur.val, buffer[cur.pos])
    cur.val -= t1
    buffer[cur.pos] -= t1

    t2 = min(cur.val, buffer[alt])
    cur.val -= t2
    buffer[alt] -= t2

    res2 = cur.val + solve(slots, buffer, pos + 1)

    cur.val += t1 + t2
    buffer[cur.pos] += t1
    buffer[alt] += t2

    return min(res1, res2)

