from functools import lru_cache

class Test:
    def __init__(self):
        self.br = sys.stdin
        self.r = 0
        self.c = 0
        self.C = [[0] * 128 for _ in range(128)]
        self.best = float('inf')
        self.cntA = [0] * 128
        self.cntB = [0] * 128
        self.cs = []
        self.cache = {}

    def readInt(self):
        try:
            c = self.br.read(1)
            while c and c.isspace():
                c = self.br.read(1)
            if not c:
                return 0
            negative = False
            if c == '-':
                negative = True
                c = self.br.read(1)
            sb = []
            while c and not c.isspace():
                sb.append(c)
                c = self.br.read(1)
            num_str = ''.join(sb)
            if not num_str:
                return 0
            result = int(num_str)
            return -result if negative else result
        except Exception:
            return 0

    def dfs(self, x, y, v1, v2):
        d = abs(x - y)
        if self.best <= 1 or d - self.C[v1][self.r] * self.C[v2][self.r] >= self.best:
            return
        if v1 == self.r - 1 and v2 == self.r - 1:
            if d < self.best:
                self.best = d
            return
        if v1 >= self.r:
            c1 = self.C[v1][self.r] - self.C[v1-1][self.r]
            s2 = self.C[v2][self.r]
            self.dfs(x, y + c1 * s2, v1 - 1, v2)
        if v2 >= self.r:
            s1 = self.C[v1][self.r]
            c2 = self.C[v2][self.r] - self.C[v2-1][self.r]
            self.dfs(x + s1 * c2, y, v1, v2 - 1)

    def solve(self, x, y, v1, v2):
        k = (x << 20) | (y << 10) | (v1 << 5) | v2
        if k in self.cache:
            return self.cache[k]
        v = 0
        d = abs(x - y)
        if d - self.C[v1][self.r] * self.C[v2][self.r] > self.best:
            self.cache[k] = v
            return v
        if v1 == 0 and v2 == 0:
            return 1
        ch = self.cs[v1 + v2 - 1]
        if v1 > 0 and ch != 'B':
            c1 = self.C[v1][self.r] - self.C[v1 - 1][self.r]
            s2 = self.C[v2][self.r]
            v += self.solve(x, y + c1 * s2, v1 - 1, v2)
        if v2 > 0 and ch != 'A':
            s1 = self.C[v1][self.r]
            c2 = self.C[v2][self.r] - self.C[v2-1][self.r]
            v += self.solve(x + s1 * c2, y, v1, v2 - 1)
        self.cache[k] = v
        return v

    def start(self):
        self.r = self.readInt()
        self.c = self.readInt()
        try:
            line = self.br.readline()
            self.cs = list(line.strip()) if line else []
        except Exception:
            self.cs = []

        for i in range(2 * (self.r + self.c) + 1):
            for j in range(2 * (self.r + self.c) + 1):
                if j == 0:
                    self.C[i][j] = 1
                elif i == 0:
                    self.C[i][j] = 0
                else:
                    self.C[i][j] = self.C[i-1][j-1] + self.C[i-1][j]

        v1 = self.r + self.c
        v2 = self.r + self.c
        x = 0
        y = 0
        while v1 >= self.r and v2 >= self.r:
            if x > y:
                c1 = self.C[v1][self.r] - self.C[v1 - 1][self.r]
                s2 = self.C[v2][self.r]
                y += c1 * s2
                v1 -= 1
            else:
                s1 = self.C[v1][self.r]
                c2 = self.C[v2][self.r] - self.C[v2-1][self.r]
                x += s1 * c2
                v2 -= 1

        self.best = abs(x - y)
        self.dfs(0, 0, self.r + self.c, self.r + self.c)

        for i in range(2 * (self.r + self.c)):
            self.cntA[i + 1] = self.cntA[i] + (1 if i < len(self.cs) and self.cs[i] == 'A' else 0)
            self.cntB[i + 1] = self.cntB[i] + (1 if i < len(self.cs) and self.cs[i] == 'B' else 0)

        ans = self.solve(0, 0, self.r + self.c, self.r + self.c)
        print(ans)

if __name__ == "__main__":
    test = Test()
    test.start()

