import java.io.*;
import java.util.*;

public class Test {
    static {
        try {
            System.setIn(new ByteArrayInputStream("0 0\n".getBytes()));
        } catch (Exception e) {}
    }

    private static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }

    int r, c;
    long[][] C = new long[128][128];
    long best = Long.MAX_VALUE;
    char[] cs;
    int[] cntA = new int[128], cntB = new int[128];
    Map<Long, Long> dp = new HashMap<>();

    long dfs(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (best <= 1 || diff - C[v1][r] * C[v2][r] >= best) return -1;
        if (v1 == r-1 && v2 == r-1) {
            best = Math.min(best, diff);
            return 1;
        }
        long res = 0;
        if (v1 >= r) {
            long c1 = C[v1][r] - C[v1-1][r], s2 = C[v2][r];
            res += dfs(x, y + c1*s2, v1-1, v2);
        }
        if (v2 >= r) {
            long s1 = C[v1][r], c2 = C[v2][r] - C[v2-1][r];
            res += dfs(x + s1*c2, y, v1, v2-1);
        }
        return res;
    }

    long memo(long x, long y, int v1, int v2) {
        long key = ((x * 31 + y) * 31 + v1) * 31 + v2;
        if (dp.containsKey(key)) return dp.get(key);
        long diff = Math.abs(x - y);
        if (diff - C[v1][r]*C[v2][r] > best) {
            dp.put(key, 0L);
            return 0;
        }
        if (v1 == 0 && v2 == 0) return 1;
        char cur = cs[v1 + v2 - 1];
        long count = 0;
        if (v1 > 0 && cur != 'B') {
            long c1 = C[v1][r] - C[v1-1][r], s2 = C[v2][r];
            count += memo(x, y + c1*s2, v1-1, v2);
        }
        if (v2 > 0 && cur != 'A') {
            long s1 = C[v1][r], c2 = C[v2][r] - C[v2-1][r];
            count += memo(x + s1*c2, y, v1, v2-1);
        }
        dp.put(key, count);
        return count;
    }

    void start() {
