class Test:
    def readInt(self):
        ans = 0
        neg = False
        try:
            start = False
            while True:
                c = sys.stdin.read(1)
                if not c:
                    break
                c = ord(c)
                if c == ord('-'):
                    start = True
                    neg = True
                    continue
                elif ord('0') <= c <= ord('9'):
                    start = True
                    ans = ans * 10 + c - ord('0')
                elif start:
                    break
        except:
            pass
        return -ans if neg else ans

    def __init__(self):
        self.r = 0
        self.c = 0
        self.C = [[0] * 64 for _ in range(64)]
        self.best = float('inf')
        self.cntA = [0] * 64
        self.cntB = [0] * 64
        self.cache = {}
        self.cs = []

    def dfs(self, x, y, v1, v2):
        d = abs(x - y)
        if self.best <= 1 or d - self.C[v1][self.r] * self.C[v2][self.r] >= self.best:
            return
        if v1 == 0 and v2 == 0:
            if d < self.best:
                self.best = d
            return
        if v1 > 0:
            c1 = self.C[v1][self.r] - self.C[v1-1][self.r]
            s2 = self.C[v2][self.r]
            self.dfs(x, y + c1 * s2, v1 - 1, v2)
        if v2 > 0:
            s1 = self.C[v1][self.r]
            c2 = self.C[v2][self.r] - self.C[v2-1][self.r]
            self.dfs(x + s1 * c2, y, v1, v2 - 1)

    def solve(self, x, y, v1, v2):
        k = x * 10000 + v1 * 100 + v2
        if k in self.cache:
            return self.cache[k]
        v = 0
        d = abs(x - y)
        if d - self.C[v1][self.r] * self.C[v2][self.r] > self.best:
            self.cache[k] = v
            return v
        if v1 == 0 and v2 == 0:
            return 1
        c = self.cs[v1 + v2 - 1]
        if v1 > 0 and c != 'B':
            c1 = self.C[v1][self.r] - self.C[v1 - 1][self.r]
            s2 = self.C[v2][self.r]
            v += self.solve(x, y + c1 * s2, v1 - 1, v2)
        if v2 > 0 and c != 'A':
            s1 = self.C[v1][self.r]
            c2 = self.C[v2][self.r] - self.C[v2-1][self.r]
            v += self.solve(x + s1 * c2, y, v1, v2 - 1)
        self.cache[k] = v
        return v

    def start(self):
        data = sys.stdin.read().splitlines()
        if not data:
            return
        parts = data[0].split()
        self.r = int(parts[0])
        self.c = int(parts[1])
        self.cs = list(data[1])

        for i in range(2 * (self.r + self.c) + 1):
            for j in range(2 * (self.r + self.c) + 1):
                if j == 0:
                    self.C[i][j] = 1
                elif i == 0:
                    self.C[i][j] = 0
                else:
                    self.C[i][j] = self.C[i-1][j-1] + self.C[i-1][j]

        v1 = self.r + self.c
        v2 = self.r + self.c
        x = 0
        y = 0
        while v1 >= self.r and v2 >= self.r:
            if x > y:
                c1 = self.C[v1][self.r] - self.C[v1 - 1][self.r]
                s2 = self.C[v2][self.r]
                y += c1 * s2
                v1 -= 1
            else:
                s1 = self.C[v1][self.r]
                c2 = self.C[v2][self.r] - self.C[v2-1][self.r]
                x += s1 * c2
                v2 -= 1

        self.best = abs(x - y)
        self.dfs(0, 0, self.r + self.c, self.r + self.c)

        for i in range(2 * (self.r + self.c)):
            self.cntA[i + 1] = self.cntA[i] + (1 if self.cs[i] == 'A' else 0)
            self.cntB[i + 1] = self.cntB[i] + (1 if self.cs[i] == 'B' else 0)

        ans = self.solve(0, 0, self.r + self.c, self.r + self.c)
        print(ans)

if __name__ == "__main__":
    test = Test()
    test.start()

