import sys

class Reader:
    def __init__(self, input_stream=sys.stdin):
        self.buffer = []
        self.index = 0
        self.input_stream = input_stream

    def read_line(self):
        line = self.input_stream.readline()
        if not line:
            return None
        return line.strip()

    def next_int(self):
        while self.index >= len(self.buffer):
            line = self.input_stream.readline()
            if not line:
                raise EOFError("No more input")
            self.buffer = line.split()
            self.index = 0
        val = int(self.buffer[self.index])
        self.index += 1
        return val

def get(w, m):
    if m == 0:
        return True
    if m % w != 0:
        return False
    m = m // w
    if m == 1:
        return True
    return get(w, m) or get(w, m - 1) or get(w, m + 1)

def main():
    reader = Reader()
    w = reader.next_int()
    m = reader.next_int()
    ans = get(w, m) or get(w, m - 1) or get(w, m + 1)
    if ans:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()

