import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        InputStream is = System.in;
        OutputStream os = System.out;
        InputReader ir = new InputReader(is);
        PrintWriter pw = new PrintWriter(os);

        int w = ir.nextInt();
        int m = ir.nextInt();
        int res = 1;

        while (m != 0) {
            int tmp = m % w;
            if (tmp == w - 1 && tmp != 1) {
                m = (m + 1) / w;
            } else if (tmp == 1) {
                m /= w;
            } else if (tmp != 0) {
                res = 0;
                break;
            } else {
                m /= w;
            }
        }

        pw.print(res == 1 ? "YES" : "NO");
        pw.flush();
        pw.close();
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar, numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new RuntimeException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

