    public static void main(String[] args) {
        InputHandler handler = new InputHandler();
        long w = handler.readLong();
        long m = handler.readLong();

        Solver solver = new Solver();
        System.out.println(solver.check(w, m) ? "YES" : "NO");
    }

    static class Solver {
        public boolean check(long w, long m) {
            long[] powers = new long[105];
            long[] cumulative = new long[105];
            long p = 1;
            int maxLevel = 0;

            for (int i = 0; i < 100; i++) {
                powers[i] = p;
                cumulative[i + 1] = p + cumulative[i];
                p *= w;
                if (p > (1L << 40)) {
                    maxLevel = i;
                    break;
                }
            }

            return tryCombinations(0, m, maxLevel, powers, cumulative);
        }

        private boolean tryCombinations(long current, long target, int level, long[] powers, long[] cumulative) {
            if (current == target) return true;
            if (level < 0) return false;

            long possibleRange = cumulative[level + 1];
            long nextPower = powers[level];

            if (current - possibleRange > target || current + possibleRange < target) {
                return false;
            }

            if (current + cumulative[level] < target) {
                return tryCombinations(current + nextPower, target, level - 1, powers, cumulative);
            } else if (current - cumulative[level] > target) {
                return tryCombinations(current - nextPower, target, level - 1, powers, cumulative);
            } else {
                return tryCombinations(current, target, level - 1, powers, cumulative);
            }
        }
    }

    static class InputHandler {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputHandler() {
            reader = new BufferedReader(new InputStreamReader(System.in));
