import sys

class FasterScanner:
    def __init__(self):
        self.buf = bytearray(1024)
        self.curChar = 0
        self.numChars = 0
        self._fill_buffer()

    def _fill_buffer(self):
        self.numChars = sys.stdin.buffer.readinto(self.buf)
        self.curChar = 0

    def read(self):
        if self.numChars == 0:
            return -1
        if self.curChar >= self.numChars:
            self.curChar = 0
            self.numChars = sys.stdin.buffer.readinto(self.buf)
            if self.numChars <= 0:
                return -1
        char = self.buf[self.curChar]
        self.curChar += 1
        return char

    def nextLine(self):
        c = self.read()
        while self._isSpaceChar(c):
            c = self.read()
        res = bytearray()
        while not self._isEndOfLine(c):
            res.append(c)
            c = self.read()
        return res.decode('ascii')

    def nextString(self):
        c = self.read()
        while self._isSpaceChar(c):
            c = self.read()
        res = bytearray()
        while not self._isSpaceChar(c):
            res.append(c)
            c = self.read()
        return res.decode('ascii')

    def nextLong(self):
        c = self.read()
        while self._isSpaceChar(c):
            c = self.read()
        sgn = 1
        if c == ord('-'):
            sgn = -1
            c = self.read()
        res = 0
        while not self._isSpaceChar(c):
            if c < ord('0') or c > ord('9'):
                raise ValueError("Input mismatch")
            res = res * 10 + (c - ord('0'))
            c = self.read()
        return res * sgn

    def nextInt(self):
        return int(self.nextLong())

    def nextIntArray(self, n):
        return [self.nextInt() for _ in range(n)]

    def nextLongArray(self, n):
        return [self.nextLong() for _ in range(n)]

    def _isSpaceChar(self, c):
        return c in (ord(' '), ord('\n'), ord('\r'), ord('\t'), -1)

    def _isEndOfLine(self, c):
        return c in (ord('\n'), ord('\r'), -1)

def main():
