        int w = Integer.parseInt(tmp[0]), m = Integer.parseInt(tmp[1]);
        boolean ok = true;
        ArrayList<Integer> all = new ArrayList<Integer>();
        while (m != 0) {
            all.add(m % w);
            m /= w;
