class Mod998:
    MOD = 998244353

    def __init__(self):
        self.factorial = [1]
        self.inv_factorial = [1]

    def fact(self, n):
        while len(self.factorial) <= n:
            self.factorial.append((self.factorial[-1] * len(self.factorial)) % self.MOD)
        return self.factorial[n]

    def f_inv(self, n):
        last_known = len(self.inv_factorial) - 1
        if last_known < n:
            f_inv = [0] * (n - last_known)
            f_inv[0] = pow(self.fact(n), self.MOD - 2, self.MOD)
            for i in range(1, len(f_inv)):
                f_inv[i] = (f_inv[i - 1] * (n - i + 1)) % self.MOD
            for i in range(len(f_inv) - 1, -1, -1):
                self.inv_factorial.append(f_inv[i])
        return self.inv_factorial[n]

    def parity_sign(self, k):
        return 1 if (k & 1) == 0 else self.MOD - 1

    def ncr(self, n, r):
        if r < 0 or n < r:
            return 0
        return (self.fact(n) * self.f_inv(r) % self.MOD) * self.f_inv(n - r) % self.MOD

    def normalize(self, x):
        x %= self.MOD
        if x < 0:
            x += self.MOD
        return x

    def add(self, a, b):
        v = a + b
        return v if v < self.MOD else v - self.MOD

    def mult(self, *args):
        r = 1
        for x in args:
            r = (r * x) % self.MOD
        return r

    def pow(self, x, e):
        if e < 0:
            x = pow(x, self.MOD - 2, self.MOD)
            e = -e
        if e == 0:
            return 1
        if e & 1:
            return (x * self.pow(x, e - 1)) % self.MOD
        return self.pow((x * x) % self.MOD, e // 2)


class InputReader:
    def __init__(self, stream):
        self.reader = stream
        self.tokenizer = None

    def next(self):
        while self.tokenizer is None or not self.tokenizer:
            try:
                line = self.reader.readline()
                if not line:
                    return None
                self.tokenizer = line.strip().split()
            except Exception:
                raise RuntimeError("IO Error")
        return self.tokenizer.pop(0)

    def next_int(self):
        return int(self.next())

    def next_long(self):
        return int(self.next())


def main():
    input_data = sys.stdin
    output_data = sys.stdout
    in_reader = InputReader(input_data)
    out = output_data

    mod = Mod998()
    n = in_reader.next_int()
    k = in_reader.next_long()

    if k == 0:
        out.write(str(mod.fact(n)) + "\n")
        return

    if k > n - 1:
