import java.io.*;
import java.util.*;

public class Main {
    private static final long MOD = 998244353L;
    private static long[] fact;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int t = 1;
        while (t-- > 0) {
            int n = sc.nextInt();
            long k = sc.nextLong();

            fact = new long[n + 1];
            fact[0] = fact[1] = 1L;
            for (int i = 2; i <= n; i++) {
                fact[i] = (fact[i - 1] * i) % MOD;
            }

            if (k == 0) {
                pw.println(fact[n]);
            } else if (k >= n) {
                pw.println(0);
            } else {
                int kVal = (int) k;
                long sum = 0L;
                long sign = 1L;
                int l = n - kVal;

                for (int i = 0; i <= l; i++) {
                    long term = modPow(l - i, n, MOD);
                    term = (term * nCr(l, l - i)) % MOD;
                    term = (term * sign) % MOD;
                    sum = (sum + term + MOD) % MOD;
                    sign = -sign;
                }

                long res = (2L * nCr(n, kVal) % MOD) * sum % MOD;
                pw.println(res);
            }
        }
        pw.close();
    }

    private static long nCr(int n, int r) {
        if (r < 0 || r > n) return 0L;
        if (r == 0 || r == n) return 1L;
        long denom = (fact[r] * fact[n - r]) % MOD;
        return (fact[n] * modPow(denom, MOD - 2, MOD)) % MOD;
    }

    private static long modPow(long base, long exp, long mod) {
        long res = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    private static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private static long solve(long x, long[] arr) {
        int n = arr.length;
        long q = x / n;
        int r = (int) (x % n);
        return arr[n - 1] * q + arr[r];
    }

