        private static final long MOD = 998244353L;
        private long[] factorial;
        private long[] invFactorial;

        public long modPow(long base, long exp) {
            long result = 1L;
            base %= MOD;
            while (exp > 0) {
                if ((exp & 1) == 1) result = (result * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return result;
        }

        public void solve(int testNum, InputReader in, PrintWriter out) {
            int maxN = 200001;
            factorial = new long[maxN];
            invFactorial = new long[maxN];
            factorial[0] = invFactorial[0] = 1L;
            for (int i = 1; i < maxN; i++) {
                factorial[i] = factorial[i - 1] * i % MOD;
                invFactorial[i] = invFactorial[i - 1] * modPow(i, MOD - 2) % MOD;
            }

            int n = in.nextInt();
            long k = in.nextLong();

            if (k >= n) {
                out.println(0);
                return;
            }
            if (k == 0) {
                out.println(factorial[n]);
                return;
            }

            int m = n - (int)k;
            long ans = 0;
            for (int i = 0; i <= m; i++) {
                long term = comb(m, i) * modPow(m - i, n) % MOD;
                ans = (i % 2 == 0) ? (ans + term) % MOD : (ans - term + MOD) % MOD;
