class TaskC:
    def solve(self, testNumber, in_reader, out):
        self.n = in_reader.nextInt()
        self.m = in_reader.nextInt()
        if self.n > self.m:
            self.n, self.m = self.m, self.n

        self.f = [[0] * self.m for _ in range(self.n)]
        self.res = math.inf
        self.cur = 0
        self.step = 1
        self.numFree = self.n * self.m
        self.dx = [-1, 0, 1, 0, 0]
        self.dy = [0, 1, 0, -1, 0]

        self.rec(0, 0)
        out.println(self.n * self.m - self.res)

    def rec(self, x, y):
        if self.numFree == 0:
            self.res = min(self.res, self.cur)
            return

        if x >= self.n:
            return
        if y >= self.m:
            self.rec(x + 1, 0)
            return

        if self.f[x][y] != 0:
            self.rec(x, y + 1)
            return

        self.put(x, y)
        self.rec(x, y + 1)
        self.remove(x, y)

        if self.isValid(x + 1, y):
