        self.n = 0
        self.m = 0
        self.dx = [-1, 0, 1, 0, 0]
        self.dy = [0, 1, 0, -1, 0]
        self.step = 0
        self.numFree = 0
        self.cur = 0
        self.res = math.inf
        self.f = []

    def run(self, rows, cols):
        self.n = rows
        self.m = cols
        self.f = [[0] * self.m for _ in range(self.n)]
        self.res = math.inf
        self.cur = 0
        self.step = 1
        self.numFree = self.n * self.m
        self.rec(0, 0)
        return int(self.res)

    def rec(self, x, y):
        if self.numFree == 0:
            self.res = min(self.res, self.cur)
            return
        if x >= self.n:
            return
        if y >= self.m:
            self.rec(x + 1, 0)
            return
        if self.f[x][y] != 0:
            self.rec(x, y + 1)
            return

        self.put(x, y)
        self.rec(x, y + 1)
        self.remove(x, y)

        if self.isValid(x + 1, y):
            self.put(x + 1, y)
            self.rec(x, y + 1)
            self.remove(x + 1, y)

        if self.isValid(x, y + 1):
            self.put(x, y + 1)
            self.rec(x, y + 1)
            self.remove(x, y + 1)

    def put(self, x, y):
        for i in range(5):
            nx = x + self.dx[i]
            ny = y + self.dy[i]
            if self.isValid(nx, ny):
                if self.f[nx][ny] == 0:
                    self.numFree -= 1
                    self.f[nx][ny] = self.step
        self.step += 1
        self.cur += 1

    def remove(self, x, y):
        self.step -= 1
        for i in range(5):
            nx = x + self.dx[i]
            ny = y + self.dy[i]
            if self.isValid(nx, ny):
                if self.f[nx][ny] == self.step:
                    self.numFree += 1
                    self.f[nx][ny] = 0
        self.cur -= 1

    def isValid(self, x, y):
        return x >= 0 and y >= 0 and x < self.n and y < self.m

def main():
    in_reader = InputReader(sys.stdin)
    out = sys.stdout

    n = in_reader.nextInt()
    m = in_reader.nextInt()

    if n > m:
        n, m = m, n

    solver = TaskC()
    res = solver.run(n, m)
    out.write(str(n * m - res) + "\n")
    out.close()

if __name__ == "__main__":
    main()

