        rd = new Reader(new BufferedReader(new InputStreamReader(System.in)));
        pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        new Main().run();
        pw.close();
    }

    int rows, cols, maskSize;
    int[] popcounts;
    int[][][] memo;

    void run() {
        rows = rd.nextInt();
        cols = rd.nextInt();
        if (rows < cols) {
            int temp = rows; rows = cols; cols = temp;
        }
        maskSize = 1 << cols;
