public class Main {
    private static class FastInput {
        final private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastInput(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
    }

    static FastInput in;
    static PrintWriter out;
    static boolean isDebug = false;
    static int logCount = 0;

    static void log(String s) {
        if (isDebug && logCount < 200) {
            out.println(s);
            out.flush();
            logCount++;
        }
    }

    public static void main(String[] args) throws IOException {
        in = new FastInput(System.in);
        out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        new Main().start();
        out.close();
    }

    int height, width, maxMask;
    int[] popCount;
    int[][][] memo;

    void start() throws IOException {
        height = in.nextInt();
        width = in.nextInt();
        if (height < width) {
            int tmp = height; height = width; width = tmp;
        }
        maxMask = 1 << width;
        popCount = new int[maxMask];
        memo = new int[height][maxMask][maxMask];

        for (int i = 0; i < maxMask; i++) popCount[i] = Integer.bitCount(i);

        for (int i = 0; i < height; i++) {
            for (int j = 0; j < maxMask; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }

        for (int mask = 0; mask < maxMask; mask++) {
            memo[0][mask][0] = popCount[mask];
        }

        int result = Integer.MAX_VALUE;

        for (int r = 0; r < height - 1; r++) {
            for (int m1 = 0; m1 < maxMask; m1++) {
                for (int m2 = 0; m2 < maxMask; m2++) {
                    if (memo[r][m1][m2] == -1) continue;
                    for (int m3 = 0; m3 < maxMask; m3++) {
                        int check = ((m1 | (m1 << 1) | (m1 >> 1) | m2 | m3) & (maxMask - 1));
                        if (check == (maxMask - 1)) {
                            int cand = memo[r][m1][m2] + popCount[m3];
                            if (memo[r + 1][m3][m2] == -1 || cand < memo[r + 1][m3][m2]) {
                                memo[r + 1][m3][m2] = cand;
                            }
                        }
                    }
                }
            }
        }

        for (int m1 = 0; m1 < maxMask; m1++) {
            for (int m2 = 0; m2 < maxMask; m2++) {
                if (memo[height - 1][m1][m2] != -1) {
                    int lastCheck = ((m1 | (m1 << 1) | (m1 >> 1) | m2) & (maxMask - 1));
                    if (lastCheck == (maxMask - 1)) {
                        result = Math.min(result, memo[height - 1][m1][m2]);
                    }
                }
            }
        }

        out.println(height * width - result);
    }
}

