    static int debugLines = 0;

    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
    }

    static FastReader scanner;
    static PrintWriter writer;

    static void log(String line) {
        if (DEBUG && debugLines < 200) {
            writer.println(line);
            writer.flush();
            debugLines++;
        }
    }

    public static void main(String[] args) throws IOException {
        scanner = new FastReader();
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        new Main().process();
        writer.close();
    }

    int n, m, limit;
    int[] ones;
    int[][][] dp;

    void process() {
        n = scanner.nextInt();
        m = scanner.nextInt();
        if (n < m) {
            int swap = n; n = m; m = swap;
        }
        limit = 1 << m;
        ones = new int[limit];
        dp = new int[n][limit][limit];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < limit; j++) {
                Arrays.fill(dp[i][j], -1);
            }
        }

        for (int mask = 0; mask < limit; mask++) {
            ones[mask] = Integer.bitCount(mask);
            dp[0][mask][0] = ones[mask];
        }

        int minSpiders = Integer.MAX_VALUE;

        for (int r = 0; r < n - 1; r++) {
            for (int prev2 = 0; prev2 < limit; prev2++) {
                for (int prev1 = 0; prev1 < limit; prev1++) {
                    if (dp[r][prev2][prev1] == -1) continue;
                    for (int curr = 0; curr < limit; curr++) {
                        int cov = ((prev2 | (prev2 << 1) | (prev2 >> 1) | prev1 | curr) & (limit - 1));
                        if (cov == (limit - 1)) {
                            int val = dp[r][prev2][prev1] + ones[curr];
                            if (dp[r + 1][curr][prev1] == -1 || val < dp[r + 1][curr][prev1]) {
                                dp[r + 1][curr][prev1] = val;
                            }
                        }
                    }
                }
            }
        }

        for (int prev2 = 0; prev2 < limit; prev2++) {
            for (int prev1 = 0; prev1 < limit; prev1++) {
                if (dp[n - 1][prev2][prev1] != -1) {
                    int cov = ((prev2 | (prev2 << 1) | (prev2 >> 1) | prev1) & (limit - 1));
                    if (cov == (limit - 1)) {
                        minSpiders = Math.min(minSpiders, dp[n - 1][prev2][prev1]);
                    }
                }
            }
        }

        writer.println(n * m - minSpiders);
    }
}

