public class cf111c {
    static int n, m, full;
    static int[][][] memo;
    static int[] popCount;

    static int popcount(int x) {
        return Integer.bitCount(x);
    }

    static boolean covers(int a, int b, int c) {
        int covered = full & (b | (b << 1) | (b >> 1) | a | c);
        return covered == full;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        if (n < m) {
            int tmp = n;
            n = m;
            m = tmp;
        }

        full = (1 << m) - 1;
        memo = new int[n + 1][1 << m][1 << m];
        popCount = new int[1 << m];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < (1 << m); j++) {
                Arrays.fill(memo[i][j], Integer.MAX_VALUE / 2);
            }
        }

        for (int i = 0; i < (1 << m); i++) {
            popCount[i] = popcount(i);
