    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        if (n > m) {
            int tmp = n;
            n = m;
            m = tmp;
        }

        int size = 1 << n;
        int[][] dp = new int[size][size];
        for (int[] row : dp) Arrays.fill(row, INF);
        Arrays.fill(dp[0], 0);

        for (int col = 0; col < m; col++) {
            int[][] nextDp = new int[size][size];
            for (int[] row : nextDp) Arrays.fill(row, INF);

            for (int prev2 = 0; prev2 < size; prev2++) {
                for (int prev1 = 0; prev1 < size; prev1++) {
                    if (dp[prev2][prev1] == INF) continue;

                    int limit = (col == m - 1) ? 1 : size;
                    for (int curr = 0; curr < limit; curr++) {
                        int fullMask = size - 1;
                        int covered = (fullMask & (prev1 >>> 1)) | (fullMask & (prev1 << 1)) | prev2 | curr;
                        covered &= (fullMask ^ prev1);

                        int added = n - Integer.bitCount(covered);
                        nextDp[prev1][curr] = Math.min(nextDp[prev1][curr], dp[prev2][prev1] + added);
                    }
                }
            }
            dp = nextDp;
        }

        int maxCovered = 0;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                maxCovered = Math.max(maxCovered, dp[i][j]);
            }
        }
        System.out.println(n * m - maxCovered);
    }
