import sys
import math
from collections import defaultdict

class Point:
    eps = 1e-8

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def add(self, o):
        return Point(self.x + o.x, self.y + o.y)

    def sub(self, o):
        return Point(self.x - o.x, self.y - o.y)

    def rotate(self, alpha):
        c = math.cos(alpha)
        s = math.sin(alpha)
        return Point(self.x * c - self.y * s, self.x * s + self.y * c)

    def norm(self):
        length = self.length()
        return self.scale(1.0 / length)

    def scale(self, f):
        return Point(f * self.x, f * self.y)

    def length(self):
        return math.sqrt(self.x * self.x + self.y * self.y)

    def __str__(self):
        return f"{self.x:.6f} {self.y:.6f}"

    def __eq__(self, other):
        if not isinstance(other, Point):
            return False
        return abs(self.x - other.x) < self.eps and abs(self.y - other.y) < self.eps

    def __lt__(self, other):
        if abs(self.x - other.x) > self.eps:
            return self.x < other.x
        if abs(self.y - other.y) > self.eps:
            return self.y < other.y
        return False

    def __hash__(self):
        return hash((round(self.x / self.eps), round(self.y / self.eps)))

class Circle:
    def __init__(self, x, y, r):
        self.x = x
        self.y = y
        self.r = r

    def center(self):
        return Point(self.x, self.y)

    def contains(self, p):
        dist = p.sub(self.center()).length()
        return abs(dist - self.r) < 1e-8

def intersect(c1, c2):
    dx = c1.x - c2.x
    dy = c1.y - c2.y
    d = math.sqrt(dx * dx + dy * dy)
    if d == 0:
        return None
    cos = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d)
    if cos < -1 - 1e-8 or cos > 1 + 1e-8:
        return None
    if cos < -1:
        cos = -1
    if cos > 1:
        cos = 1
    res = []
    alpha = math.acos(cos)
    dir_vec = Point(c2.x - c1.x, c2.y - c1.y).norm()
    res.append(c1.center().add(dir_vec.scale(c1.r).rotate(alpha)))
    res.append(c1.center().add(dir_vec.scale(c1.r).rotate(-alpha)))
    return res

def dfs(i, was, adj):
    was[i] = True
    for j in adj[i]:
        if not was[j]:
            dfs(j, was, adj)

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    n = int(input_data[0].strip())
    circles = []
    for i in range(1, n + 1):
        parts = input_data[i].split()
        x = int(parts[0])
        y = int(parts[1])
        r = int(parts[2])
        circles.append(Circle(x, y, r))

    all_points = set()
    for i in range(n):
        for j in range(i + 1, n):
            inter = intersect(circles[i], circles[j])
            if inter:
                for p in inter:
                    all_points.add(p)

    point_id = {}
    adj = []

    def get_id(p):
        if p not in point_id:
            sz = len(point_id)
            point_id[p] = sz
            adj.append(set())
        return point_id[p]

    for i in range(n):
        angles = []
        K = 100
        for j in range(K):
            angles.append(math.pi * 2 * j / K)

        for p in all_points:
            if circles[i].contains(p):
                dx = p.x - circles[i].x
                dy = p.y - circles[i].y
                alpha = math.atan2(dy, dx)
                if alpha < 0:
                    alpha += 2 * math.pi
                angles.append(alpha)

        angles = sorted(set(angles))
        dir_vec = Point(circles[i].r, 0)

        for j in range(len(angles)):
            p = circles[i].center().add(dir_vec.rotate(angles[j]))
            get_id(p)

        for j in range(len(angles)):
            p = circles[i].center().add(dir_vec.rotate(angles[j]))
            q = circles[i].center().add(dir_vec.rotate(angles[(j + 1) % len(angles)]))
            u = point_id[p]
            v = point_id[q]
            if u != v:
                adj[u].add(v)
                adj[v].add(u)

    v = len(adj)
    e = sum(len(s) for s in adj) // 2

    comps = 0
    was = [False] * v
    for i in range(v):
        if not was[i]:
            comps += 1
            dfs(i, was, adj)

    result = 1 + comps + e - v
    print(result)

if __name__ == "__main__":
    main()

