import sys
import math
from collections import defaultdict

class Vec:
    EPS = 1e-9

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def add(self, o):
        return Vec(self.x + o.x, self.y + o.y)

    def sub(self, o):
        return Vec(self.x - o.x, self.y - o.y)

    def scale(self, s):
        return Vec(self.x * s, self.y * s)

    def dot(self, o):
        return self.x * o.x + self.y * o.y

    def cross(self, o):
        return self.x * o.y - self.y * o.x

    def mag2(self):
        return self.dot(self)

    def mag(self):
        return math.sqrt(self.mag2())

    def unit(self):
        m = self.mag()
        if m == 0:
            return Vec(0, 0)
        return self.scale(1 / m)

    def rot90(self):
        return Vec(-self.y, self.x)

    def rot270(self):
        return Vec(self.y, -self.x)

    def rotate(self, theta):
        newX = self.x * math.cos(theta) + self.y * math.cos(math.pi / 2 + theta)
        newY = self.x * math.sin(theta) + self.y * math.sin(math.pi / 2 + theta)
        return Vec(newX, newY)

    def angle(self):
        return (math.atan2(self.y, self.x) + 2 * math.pi) % (2 * math.pi)

    def __str__(self):
        return f"({self.x:.2f}, {self.y:.2f})"

    @staticmethod
    def eq(a, b):
        return abs(a - b) < Vec.EPS

    def __eq__(self, other):
        if not isinstance(other, Vec):
            return False
        return Vec.eq(self.x, other.x) and Vec.eq(self.y, other.y)

    def __hash__(self):
        # Use rounded values for hashing to handle floating point precision
        return hash((round(self.x / Vec.EPS), round(self.y / Vec.EPS)))

class Circle:
    def __init__(self, c, r):
        self.c = c
        self.r = r

    def contains(self, v):
        return self.c.sub(v).mag2() - Vec.EPS * Vec.EPS <= self.r * self.r

    def intersect(self, o):
        if self.c == o.c:
            return None

        dir_vec = o.c.sub(self.c)
        d2 = dir_vec.mag2()
        d = math.sqrt(d2)

        if self.r + o.r < d or self.r + d < o.r or o.r + d < self.r:
            return None

        if Vec.eq(self.r + o.r, d) or Vec.eq(o.r + d, self.r):
            return [self.c.add(dir_vec.scale(self.r / d))]

        if Vec.eq(self.r + d, o.r):
            return [self.c.sub(dir_vec.scale(self.r / d))]

        d1 = (self.r * self.r + d2 - o.r * o.r) / (2 * d)
        h = math.sqrt(max(0, self.r * self.r - d1 * d1))
