public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int n = Integer.parseInt(br.readLine().trim());
            String s = br.readLine().trim();

            int nk = 0, nv = 0, no = 0;
            int[] kpos = new int[n];
            int[] vpos = new int[n];
            int[] opos = new int[n];

            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                if (c == 'K') kpos[nk++] = i;
                else if (c == 'V') vpos[nv++] = i;
                else opos[no++] = i;
            }

            int[] snk = new int[n + 1];
            int[] snv = new int[n + 1];
            int[] sno = new int[n + 1];

            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                snk[i + 1] = snk[i] + (c == 'K' ? 1 : 0);
                snv[i + 1] = snv[i] + (c == 'V' ? 1 : 0);
                sno[i + 1] = sno[i] + (c == 'O' ? 1 : 0);
            }

            final int INF = (int)1e9;
            int[][][][] dp = new int[2][nk + 1][nv + 1][no + 1];

            for (int[][][] a : dp) {
                for (int[][] b : a) {
                    for (int[] c : b) {
                        Arrays.fill(c, INF);
                    }
                }
            }

            dp[0][0][0][0] = 0;

            for (int k = 0; k <= nk; k++) {
                for (int v = 0; v <= nv; v++) {
                    for (int o = 0; o <= no; o++) {
                        for (int hv = 0; hv < 2; hv++) {
                            int cur = dp[hv][k][v][o];
                            if (cur == INF) continue;

                            if (k < nk && hv == 0) {
                                int cost = Math.max(snv[kpos[k]] - v, 0) + Math.max(sno[kpos[k]] - o, 0);
                                dp[0][k + 1][v][o] = Math.min(dp[0][k + 1][v][o], cur + cost);
                            }
                            if (v < nv) {
                                int cost = Math.max(snk[vpos[v]] - k, 0) + Math.max(sno[vpos[v]] - o, 0);
                                dp[1][k][v + 1][o] = Math.min(dp[1][k][v + 1][o], cur + cost);
                            }
                            if (o < no) {
                                int cost = Math.max(snv[opos[o]] - v, 0) + Math.max(snk[opos[o]] - k, 0);
                                dp[0][k][v][o + 1] = Math.min(dp[0][k][v][o + 1], cur + cost);
                            }
                        }
                    }
                }
            }

            int ans = Math.min(dp[0][nk][nv][no], dp[1][nk][nv][no]);
            pw.println(ans);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

