        if (System.getProperty("ONLINE_JUDGE") == null) {
            System.out.println((System.currentTimeMillis() - start) + "ms");
        }
    }

    void solve() {
        int n = ni();
        char[] s = ns(n);

        int nv = 0, nk = 0, ne = 0;
        for (char c : s) {
            if (c == 'V') nv++;
            else if (c == 'K') nk++;
            else ne++;
        }

        int[][][][] dp = new int[3][nv + 1][nk + 1][ne + 1];
        for (int i = 0; i <= nv; i++) {
            for (int j = 0; j <= nk; j++) {
                for (int k = 0; k <= ne; k++) {
                    Arrays.fill(dp[0][i][j], Integer.MAX_VALUE / 2);
                    Arrays.fill(dp[1][i][j], Integer.MAX_VALUE / 2);
                    Arrays.fill(dp[2][i][j], Integer.MAX_VALUE / 2);
                }
            }
        }
        dp[2][0][0][0] = 0;

        int[][][][] poss = new int[3][nv + 1][nk + 1][ne + 1];
        for (int i = 0; i <= nv; i++) {
            for (int j = 0; j <= nk; j++) {
                for (int k = 0; k <= ne; k++) {
                    for (int l = 0; l < 3; l++) {
                        poss[l][i][j][k] = getPosition(s, i, j, k, l);
                    }
                }
            }
        }

        for (int i = 0; i <= nv; i++) {
            for (int j = 0; j <= nk; j++) {
                for (int k = 0; k <= ne; k++) {
                    if (i + 1 <= nv && poss[0][i][j][k] != -1) {
                        int v = poss[0][i][j][k];
                        dp[0][i + 1][j][k] = Math.min(dp[0][i + 1][j][k], dp[0][i][j][k] + v);
                        dp[0][i + 1][j][k] = Math.min(dp[0][i + 1][j][k], dp[1][i][j][k] + v);
                        dp[0][i + 1][j][k] = Math.min(dp[0][i + 1][j][k], dp[2][i][j][k] + v);
                    }
                    if (j + 1 <= nk && poss[1][i][j][k] != -1) {
                        int v = poss[1][i][j][k];
                        dp[1][i][j + 1][k] = Math.min(dp[1][i][j + 1][k], dp[1][i][j][k] + v);
                        dp[1][i][j + 1][k] = Math.min(dp[1][i][j + 1][k], dp[2][i][j][k] + v);
                    }
                    if (k + 1 <= ne && poss[2][i][j][k] != -1) {
                        int v = poss[2][i][j][k];
                        dp[2][i][j][k + 1] = Math.min(dp[2][i][j][k + 1], dp[2][i][j][k] + v);
                        dp[2][i][j][k + 1] = Math.min(dp[2][i][j][k + 1], dp[1][i][j][k] + v);
                        dp[2][i][j][k + 1] = Math.min(dp[2][i][j][k + 1], dp[0][i][j][k] + v);
                    }
                }
            }
        }

        int result = Math.min(dp[0][nv][nk][ne], Math.min(dp[1][nv][nk][ne], dp[2][nv][nk][ne]));
        out.println(result);
    }

    int getPosition(char[] s, int a, int b, int c, int type) {
        int ret = 0;
        for (char ch : s) {
            if (ch == 'V') {
                if (a == 0) {
                    if (type == 0) return ret;
                    ret++;
                } else {
                    a--;
                }
            } else if (ch == 'K') {
                if (b == 0) {
                    if (type == 1) return ret;
                    ret++;
                } else {
                    b--;
                }
            } else {
                if (c == 0) {
                    if (type == 2) return ret;
                    ret++;
                } else {
                    c--;
                }
            }
        }
        return -1;
    }

    private int readByte() {
        try {
            return is.read();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }

    private int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b));
        return b;
    }

    private String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b))) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !(isSpaceChar(b))) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }
}

