                    for (int pos = 0; pos < 2; pos++) {
                        char required = ending.charAt(pos);
                        char present = digits[length - 2 + pos];

                        if (present == '_') continue;
                        if (present == 'X') {
                            int expectedDigit = required - '0';
                            if (knownX == -1) knownX = expectedDigit;
                            else if (knownX != expectedDigit) {
