            self.log[i] = 1 + self.log[i // 2]

    def build(self, arr):
        n = len(arr)
        for i in range(n - 1, -1, -1):
            for j in range(25):
                r = i + (1 << j) - 1
                if r >= n:
                    break
                if j == 0:
                    self.st[i][j] = arr[i]
                else:
                    self.st[i][j] = min(self.st[i][j - 1], self.st[i + (1 << (j - 1))][j - 1])

    def gcd(self, a, b):
        if a == 0:
            return b
        return self.gcd(b % a, a)

    def query(self, l, r):
        w = r - l + 1
        power = self.log[w]
        return min(self.st[l][power], self.st[r - (1 << power) + 1][power])

def back(arr):
    n = len(arr)
    global flag

    def fnc(i):
        return arr[i] != '_'

    if fnc(n - 1) and fnc(n - 2):
        num = int(str(arr[n - 2]) + str(arr[n - 1]))
        if num % 25 == 0:
            if num == 0:
