public class div25_v2 {
    private static char[] input;
    private static int len;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        input = br.readLine().toCharArray();
        len = input.length;
        int result = 0;
        if (len == 1) {
            char ch = input[0];
            if (ch == 'X' || ch == '_' || (Character.isDigit(ch) && ch == '0')) {
                result = 1;
            }
        } else {
            result += compute(2, 5);
            result += compute(5, 0);
            result += compute(7, 5);
            result += compute(0, 0);
        }
        System.out.println(result);
    }

    private static int compute(int e1, int e2) {
        if (len == 2 && e1 == 0) return 0;
        int xVal = -1;
        if (input[len - 2] == 'X') {
            xVal = e1;
        } else if (input[len - 2] != '_') {
            int v = toInt(len - 2);
            if (v != e1) return 0;
        }
        if (input[len - 1] == 'X') {
            if (xVal != -1 && e2 != xVal) return 0;
            else xVal = e2;
        } else if (input[len - 1] != '_') {
            int v = toInt(len - 1);
            if (v != e2) return 0;
        }
        long count = 1;
        for (int idx = 0; idx < len - 2; idx++) {
            if (idx == 0) {
                if (input[idx] == 'X' && xVal == 0) return 0;
                if (toInt(0) == 0) return 0;
            }
            if (input[idx] == '_') {
                count *= (idx == 0) ? 9 : 10;
            } else if (input[idx] == 'X') {
                if (xVal != -1) continue;
                xVal = 10;
                count *= (idx == 0) ? 9 : 10;
            }
        }
        return (int) count;
    }

    private static int toInt(int idx) {
        char c = input[idx];
        if (c == '_' || c == 'X') return -1;
        return c - '0';
    }
}

