def clean(a):
    last = len(a) - 1
    while last >= 0 and a[last] == 0:
        last -= 1
    return a[:last+1] if last >= 0 else []

def polySquare(a):
    len_a = len(a)
    res = [0] * (2 * len_a - 1)
    for i in range(len_a):
        for j in range(i, len_a):
            prod = a[i] * a[j]
            if i == j:
                res[i + j] = (res[i + j] + prod) % MOD
            else:
                res[i + j] = (res[i + j] + 2 * prod) % MOD
    return res

def polyMultiply(a, b):
    len_a = len(a)
    len_b = len(b)
    res = [0] * (len_a + len_b - 1)
    for i in range(len_a):
        for j in range(len_b):
            res[i + j] = (res[i + j] + a[i] * b[j]) % MOD
    return res

