        }

        public int readInt() {
            int c = read();
            while (c <= ' ') c = read();
            int sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            int num = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') throw new NumberFormatException();
                num = num * 10 + c - '0';
                c = read();
            }
