import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static final int MOD = 998244353;
    static final int G = 3;

    static long modPow(long base, long exp) {
        base %= MOD;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static void bitReverse(long[] arr, int n) {
        for (int i = 1, j = n >> 1; i < n - 1; i++) {
            if (i < j) {
                long tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
            }
            int k = n >> 1;
            while (j >= k) {
                j -= k;
                k >>= 1;
            }
            if (j < k) j += k;
        }
    }

    static void ntt(long[] arr, int n, int sign) {
        bitReverse(arr, n);
        for (int h = 2; h <= n; h <<= 1) {
            long wn = modPow(G, (MOD - 1) / h);
            if (sign == -1) wn = modPow(wn, MOD - 2);
            for (int j = 0; j < n; j += h) {
                long w = 1;
                for (int k = j; k < j + h / 2; k++) {
                    long u = arr[k];
                    long t = (w * arr[k + h / 2]) % MOD;
                    arr[k] = (u + t) % MOD;
                    arr[k + h / 2] = ((u - t) % MOD + MOD) % MOD;
                    w = (w * wn) % MOD;
                }
            }
        }
        if (sign == -1) {
            long invN = modPow(n, MOD - 2);
            for (int i = 0; i < n; i++) {
                arr[i] = (arr[i] * invN) % MOD;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int len = 1;
        int nn = n / 2;
        while (len < 9 * nn + 1) len <<= 1;

        long[] a = new long[len];
        long[] b = new long[len];
        a[0] = 1;

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < m; i++) {
            int x = Integer.parseInt(st.nextToken());
            b[x] = 1;
        }

        ntt(a, len, 1);
        ntt(b, len, 1);

        for (int i = 0; i < len; i++) {
            if (a[i] != 0 && b[i] != 0) {
                a[i] = (a[i] * modPow(b[i], nn)) % MOD;
            } else {
                a[i] = 0;
            }
        }

        ntt(a, len, -1);

        long ans = 0;
        for (int i = 0; i < len; i++) {
