        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    int readInt() {
        return Integer.parseInt(nextToken());
    }

    String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(consoleInput.readLine());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return tokenizer.nextToken();
    }

    StringTokenizer tokenizer;

    public static void main(String[] args) {
        new FFT().setup();
    }
}

