    def mod_inverse(a, m):
        # Extended Euclidean Algorithm
        def extended_gcd(a, b):
            if a == 0:
                return b, 0, 1
            gcd, x1, y1 = extended_gcd(b % a, a)
            x = y1 - (b // a) * x1
            y = x1
            return gcd, x, y

        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            raise ValueError("Modular inverse does not exist")
        else:
            return (x % m + m) % m

    @staticmethod
    def initialize():
        FFT.ROOT_POWERS[0] = 1
        FFT.ROOT_INV_POWERS[0] = 1
        for i in range(1, FFT.SIZE):
            FFT.ROOT_POWERS[i] = (FFT.ROOT_POWERS[i-1] * FFT.ROOT) % FFT.MOD
            FFT.ROOT_INV_POWERS[i] = (FFT.ROOT_INV_POWERS[i-1] * FFT.ROOT) % FFT.MOD
        FFT.SIZE_INVERSE = FFT.mod_inverse(FFT.SIZE, FFT.MOD)

