                high[1 - side] += span;
                rotCount++;
                traverse(1 - side, low, high, R[pos], pos + 1, false);
                rotCount--;
                high[side] -= span;
                high[1 - side] -= span;

                // two rotations
                high[side] += span;
                low[1 - side] += 1;
                high[1 - side] += span - 1;
