            if (A[idx] == B[idx]) {
                solve(side, minVal, maxVal, cur, idx + 1, false);
                currentRotations++;
                solve(1 - side, minVal, maxVal, cur, idx + 1, false);
                currentRotations--;
            } else {
                int span = B[idx] - A[idx];

                // no rotate
                minVal[side] += span;
                maxVal[side] += span;
                solve(side, minVal, maxVal, B[idx], idx + 1, false);
                minVal[side] -= span;
                maxVal[side] -= span;

                // rotate once
                maxVal[side] += span;
                maxVal[1 - side] += span;
                currentRotations++;
                solve(1 - side, minVal, maxVal, B[idx], idx + 1, false);
                currentRotations--;
                maxVal[side] -= span;
                maxVal[1 - side] -= span;

                // rotate twice
                maxVal[side] += span;
                minVal[1 - side] += 1;
                maxVal[1 - side] += span - 1;
                currentRotations += 2;
                solve(side, minVal, maxVal, B[idx], idx + 1, false);
                currentRotations -= 2;
                maxVal[side] -= span;
                minVal[1 - side] -= 1;
                maxVal[1 - side] -= span - 1;
            }
        } else {
            int shift = A[idx] - cur;
            minVal[side] += shift;
            maxVal[side] += shift;
            solve(side, minVal, maxVal, A[idx], idx, true);
            minVal[side] -= shift;
            maxVal[side] -= shift;
        }
    }

    static int currentRotations = 0;

    public static void main(String[] args) throws IOException {
