    n = scanner.next_int()
    k = scanner.next_int()
    segs = []
    for _ in range(k):
        l = scanner.next_int()
        r = scanner.next_int()
        segs.append([l, r])

    segs.sort(key=lambda x: x[0])

    finSeg = []
    i = 0
    while i < k:
