    k = len(finSeg)
    segs = finSeg[:]
    l_arr = [segs[i][1] - segs[i][0] for i in range(k)]
    delt = []
    for i in range(k):
        if i < k - 1:
            delt.append(segs[i+1][0] - segs[i][1])
        else:
            delt.append(2 * n - segs[i][1])

