        dp[0] = new SegmentTree(N + 1);
        dp[1] = new SegmentTree(N + 1);
        dp[0].update(0, 0);

        int cur = 0;
        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];
            int len = end - start;

            for (int j = N; j >= 0; j--) {
                dp[0].update(j, dp[0].getValue(j - len));
            }
            cur = end;

            SegmentTree[] nextDp = new SegmentTree[]{new SegmentTree(N + 1), new SegmentTree(N + 1)};

            for (int j = 0; j <= N; j++) {
                int[] candidates = new int[2];
                for (int side = 0; side < 2; side++) {
                    int twoSwaps = dp[side].minQuery(j - len, j);
                    int oneSwap = dp[1 - side].minQuery(j - len, j);
                    int noSwap = (side == 1) ? dp[side].getValue(j) : dp[side].getValue(j - len);
                    candidates[side] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                }
                nextDp[0].update(j, candidates[0]);
                nextDp[1].update(j, candidates[1]);
            }

            dp = nextDp;
        }

        int ans = Math.min(dp[0].minQuery(N, N), dp[1].minQuery(N, N));
        if (ans >= (int)(1e9)) {
            out.println("Hungry");
        } else {
            out.println("Full");
            out.println(ans);
        }
        out.close();
    }

    static class SegmentTree {
        private final int[] seg;
        private final int[] base;
        private final int n;

        public SegmentTree(int size) {
            n = size;
            base = new int[n];
            seg = new int[4 * n];
            Arrays.fill(base, (int)(1e9));
            Arrays.fill(seg, (int)(1e9));
        }

        public void update(int idx, int val) {
            base[idx] = val;
            int node = 1, l = 0, r = n - 1;
            while (l < r) {
                int mid = (l + r) >>> 1;
                if (idx <= mid) {
                    r = mid;
                    node <<= 1;
                } else {
                    l = mid + 1;
                    node = (node << 1) | 1;
                }
            }
            seg[node] = val;
            for (node >>= 1; node > 0; node >>= 1) {
                seg[node] = Math.min(seg[node << 1], seg[(node << 1) | 1]);
            }
        }

        public int getValue(int idx) {
            return idx < 0 ? (int)(1e9) : base[idx];
        }

        public int minQuery(int ql, int qr) {
            if (qr < 0) return (int)(1e9);
            return query(1, 0, n - 1, Math.max(0, ql), qr);
        }

        private int query(int node, int tl, int tr, int l, int r) {
            if (l > r) return (int)(1e9);
            if (l == tl && r == tr) return seg[node];
            int mid = (tl + tr) >>> 1;
            return Math.min(
                query(node << 1, tl, mid, l, Math.min(r, mid)),
                query((node << 1) | 1, mid + 1, tr, Math.max(l, mid + 1), r)
            );
        }
    }

