class FastScanner:
    def __init__(self, stream):
        self.stream = stream
        self.buffer = []
        self.pos = 0

    def read(self):
        if self.pos >= len(self.buffer):
            self.buffer = list(self.stream.read(1))
            self.pos = 0
            if not self.buffer:
                return -1
        val = self.buffer[self.pos]
        self.pos += 1
        return val

    def next(self):
        sb = []
        c = self.read()
        while c >= 0 and self.is_whitespace(c):
            c = self.read()
        if c < 0:
            return None
        while c >= 0 and not self.is_whitespace(c):
            sb.append(chr(c))
            c = self.read()
        return ''.join(sb)

    @staticmethod
    def is_whitespace(c):
        return c >= 0 and c <= 32

    def read_line(self):
        try:
            return self.stream.readline()
        except:
            return None


