public class C {
    private static final int INF = (int)1e6;
    private static int[][][][] memo;
    private static String inputStr;

    private static int dp(int idx, int pos, int neg, int carry) {
        int trueCarry = carry - 50;
        if (idx == 17) {
            return (pos + neg + trueCarry == 0) ? 0 : INF;
        }
        if (memo[idx][pos][neg][carry] != -1) {
            return memo[idx][pos][neg][carry];
        }
        int minCost = INF;
        int maxPos = Math.min(15, pos);
        int maxNeg = Math.min(15, neg);
        for (int i = 0; i <= maxPos; i++) {
            for (int j = 0; j <= maxNeg; j++) {
                int total = pos - neg + trueCarry;
                int digit = (total % 10 + 10) % 10;
                int nextCarry = total > 0 ? total / 10 : (total - 9) / 10;
                if (digit != inputStr.charAt(idx) - '0') continue;
                int cost = dp(idx + 1, pos - i, neg - j, nextCarry + 50) + (i + j) * (idx + 1);
                if (cost < minCost) minCost = cost;
            }
        }
        memo[idx][pos][neg][carry] = minCost;
        return minCost;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int bound = 50;
        memo = new int[20][bound][bound][100];
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < bound; j++) {
                for (int k = 0; k < bound; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
        inputStr = Long.toString(n);
        while (inputStr.length() < 17) {
            inputStr = "0" + inputStr;
        }
        inputStr = new StringBuilder(inputStr).reverse().toString();
        int result = INF;
        for (int p = 0; p < bound; p++) {
            for (int q = 0; q < bound; q++) {
                int candidate = dp(0, p, q, 50);
                if (candidate < result) result = candidate;
            }
        }
        System.out.println(result);
    }
}

