def go(n):
    if n == 0:
        return 0
    k = 1
    cnt = 1
    while k * 10 + 1 < n:
        k = k * 10 + 1
        cnt += 1
    rem1 = n % k
    div1 = n // k
    rem2 = (k * 10 + 1 - n) % k
    div2 = (k * 10 + 1 - n) // k
    val1 = go(rem1) + div1 * cnt
    val2 = go(rem2) + (cnt + 1) + div2 * cnt
    return min(val1, val2)

