public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class Input {
        private final byte[] buf = new byte[1 << 15];
        private int idx = 0, len = 0;
        private final InputStream in;

        Input(InputStream is) { in = is; }

        private int next() throws IOException {
            if (idx >= len) {
                len = in.read(buf);
                idx = 0;
                if (len <= 0) return -1;
            }
            return buf[idx++];
        }

        int nextInt() throws IOException {
            int c;
            while ((c = next()) <= 32) if (c == -1) return -1;
            int x = 0;
            while (c > 32) {
                x = x * 10 + c - '0';
                c = next();
            }
            return x;
        }
    }

    Input input;

    public static void main(String[] args) {
        CF1187G solver = new CF1187G();
        solver.input = new Input(System.in);
        solver.process();
        solver.flush();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] adj;
    int N, M;
    int[] pi, dist, prevEdge;
    int[] from, to, xorVal, cost;
    int[] cap;

    void build(int nodes, int edges) {
        adj = new ArrayList[nodes];
        for (int i = 0; i < nodes; i++) adj[i] = new ArrayList<>();
        pi = new int[nodes];
        dist = new int[nodes];
        prevEdge = new int[nodes];
        from = new int[edges];
        to = new int[edges];
        xorVal = new int[edges];
        cost = new int[edges];
        cap = new int[edges * 2];
        M = 0;
    }

    void add(int u, int v, int capacity, int c) {
        int i = M++;
        from[i] = u;
        to[i] = v;
        xorVal[i] = u ^ v;
        cost[i] = c;
        cap[i * 2] = capacity;
        adj[u].add(i * 2);
        adj[v].add(i * 2 + 1);
    }

    int[] q;
    int qf, qb, ql;
    boolean[] inq;

    void push(int x) {
        if (inq[x]) return;
        if (qf + qb == q.length) {
            if (ql * 2 <= q.length) {
                System.arraycopy(q, qf, q, 0, ql);
            } else {
                int[] nq = new int[q.length * 2];
                System.arraycopy(q, qf, nq, 0, ql);
                q = nq;
            }
            qf = 0;
        }
        q[qf + qb++] = x;
        inq[x] = true;
    }

    int pop() {
        int x = q[qf++];
        ql--;
        inq[x] = false;
        return x;
    }

    boolean spfa(int s, int t) {
        Arrays.fill(pi, INF);
        pi[s] = 0;
        qf = qb = 0;
        push(s);

        while (ql > 0) {
            int u = pop();
            int nd = dist[u] + 1;

            for (int e : adj[u]) {
                if (cap[e] > 0) {
                    int idx = e >> 1;
                    int c = (e & 1) == 0 ? cost[idx] : -cost[idx];
                    int np = pi[u] + c;
                    int v = u ^ xorVal[idx];

                    if (pi[v] > np || (pi[v] == np && dist[v] > nd)) {
                        pi[v] = np;
                        dist[v] = nd;
                        prevEdge[v] = e;
                        push(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    void augment(int s, int t) {
        int minCap = INF;
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            minCap = Math.min(minCap, cap[prevEdge[v]]);
        }
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            cap[e] -= minCap;
            cap[e ^ 1] += minCap;
        }
    }

    void augmentUnit(int s, int t) {
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            cap[e]--;
            cap[e ^ 1]++;
        }
    }

    int minCostFlow(int s, int t) {
        while (spfa(s, t)) {
            augmentUnit(s, t);
        }
        int total = 0;
        for (int i = 0; i < M; i++) {
            total += cost[i] * cap[i * 2 + 1];
        }
        return total;
    }

    void process() {
        try {
            int n = input.nextInt();
            int m = input.nextInt();
            int k = input.nextInt();
            int c = input.nextInt();
            int d = input.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) {
                special[i] = input.nextInt() - 1;
            }

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = input.nextInt() - 1;
                int v = input.nextInt() - 1;
                g[u].add(v);
                g[v].add(u);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);

            build(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int w : g[i]) {
                        int v = w * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            add(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    add(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                add(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(minCostFlow(totalNodes - 1, 0 * T + T - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

import java.io.*;
