public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class FastInput {
        private final byte[] buffer = new byte[1 << 15];
        private int pos = 0, size = 0;
        private final InputStream stream;

        FastInput(InputStream is) { stream = is; }

        private int fetch() throws IOException {
            if (pos >= size) {
                size = stream.read(buffer);
                pos = 0;
                if (size <= 0) return -1;
            }
            return buffer[pos++];
        }

        int nextInt() throws IOException {
            int ch;
            while ((ch = fetch()) <= 32) if (ch == -1) return -1;
            int num = 0;
            while (ch > 32) {
                num = num * 10 + ch - '0';
                ch = fetch();
            }
            return num;
        }
    }

    FastInput in;

    public static void main(String[] args) {
        CF1187G solver = new CF1187G();
        solver.in = new FastInput(System.in);
        solver.run();
        solver.flush();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] graph;
    int nodeCount, edgeCount;
    int[] potential, level, prevEdge;
    int[] src, dst, xorEdge, weight;
    int[] capacity;

    void setup(int n, int m) {
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        potential = new int[n];
        level = new int[n];
        prevEdge = new int[n];
        src = new int[m];
        dst = new int[m];
        xorEdge = new int[m];
        weight = new int[m];
        capacity = new int[m * 2];
        edgeCount = 0;
    }

    void link(int u, int v, int cap, int c) {
        int idx = edgeCount++;
        src[idx] = u;
        dst[idx] = v;
        xorEdge[idx] = u ^ v;
        weight[idx] = c;
        capacity[idx * 2] = cap;
        graph[u].add(idx * 2);
        graph[v].add(idx * 2 + 1);
    }

    int[] queue;
    int queueStart, queueEnd, queueLength;
    boolean[] inQueue;

    void offer(int v) {
        if (inQueue[v]) return;
        if (queueStart + queueEnd == queue.length) {
            if (queueLength * 2 <= queue.length) {
                System.arraycopy(queue, queueStart, queue, 0, queueLength);
            } else {
                int[] newQueue = new int[queue.length * 2];
                System.arraycopy(queue, queueStart, newQueue, 0, queueLength);
                queue = newQueue;
            }
            queueStart = 0;
        }
        queue[queueStart + queueEnd++] = v;
        inQueue[v] = true;
    }

    int poll() {
        int v = queue[queueStart++];
        queueLength--;
        inQueue[v] = false;
        return v;
    }

    boolean findPath(int source, int sink) {
        Arrays.fill(potential, INF);
        potential[source] = 0;
        queueStart = queueEnd = 0;
        offer(source);

        while (queueLength > 0) {
            int u = poll();
            int newLevel = level[u] + 1;

            for (int edge : graph[u]) {
                if (capacity[edge] > 0) {
                    int idx = edge >> 1;
                    int c = (edge & 1) == 0 ? weight[idx] : -weight[idx];
                    int newPotential = potential[u] + c;
                    int v = u ^ xorEdge[idx];

                    if (potential[v] > newPotential || 
                        (potential[v] == newPotential && level[v] > newLevel)) {
                        potential[v] = newPotential;
                        level[v] = newLevel;
                        prevEdge[v] = edge;
                        offer(v);
                    }
                }
            }
        }
        return potential[sink] != INF;
    }

    void augment(int source, int sink) {
        int minCap = INF;
        for (int v = sink; v != source; v ^= xorEdge[prevEdge[v] >> 1]) {
            minCap = Math.min(minCap, capacity[prevEdge[v]]);
        }
        for (int v = sink; v != source; v ^= xorEdge[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            capacity[e] -= minCap;
            capacity[e ^ 1] += minCap;
        }
    }

    void augmentUnit(int source, int sink) {
        for (int v = sink; v != source; v ^= xorEdge[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            capacity[e]--;
            capacity[e ^ 1]++;
        }
    }

    int minCostMaxFlow(int source, int sink) {
        while (findPath(source, sink)) {
            augmentUnit(source, sink);
        }
        int total = 0;
        for (int i = 0; i < edgeCount; i++) {
            total += weight[i] * capacity[i * 2 + 1];
        }
        return total;
    }

    void run() {
        try {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();
            int c = in.nextInt();
            int d = in.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) {
                special[i] = in.nextInt() - 1;
            }

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                g[u].add(v);
                g[v].add(u);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);

            setup(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int neighbor : g[i]) {
                        int v = neighbor * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            link(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    link(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                link(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(minCostMaxFlow(totalNodes - 1, 0 * T + T - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

import java.io.*;
import java.util.*;
public class G{
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.flush();out.close();
    }
        static class TaskE {
        class MinCostMaxFlow{
                ArrayList<Edge> al[];
                Edge ja[][]; 
                int d[]; // shortest distances
                int N , S , T , maxFlow ; int minCost;
                final int gmax = Integer.MAX_VALUE / 100;

                int edges = 0;

                class Edge{
                    int u , flow, rid, cost;
                    Edge(int a, int b, int c, int d){u = a; flow = b; cost = c; rid = d;}
                }

                void addEdge(int u , int v , int flow , int cost){
                    int lu = al[u].size(), lv = al[v].size();
                    al[u].add(new Edge(v, flow, cost, lv)); 
                    al[v].add(new Edge(u, 0, -cost, lu));   
                }

                void convertToArray(){
                    ja = new Edge[N][];
                    for(int i = 0; i < N; i++){
                        int sz = al[i].size();
                        ja[i] = new Edge[sz];
                        for(int j = 0; j < sz; j++){
                            ja[i][j] = al[i].get(j);
                        }
                        al[i].clear();
                    }
                }

                MinCostMaxFlow(int n , int source , int sink){
                    N = n; S = source; T = sink; maxFlow = 0; minCost = 0;
                    al = new ArrayList[N];
                    d = new int[N];
                    for(int i = 0; i < N; i++){
                        al[i] = new ArrayList<>();
                    }
                }

                boolean BellmanFord(boolean check){
                    d[0] = 0;
                    for(int i = 0; i < N - 1; i++){
                        for(int j = 0; j < N; j++){
                            for(Edge e : ja[j]){
                                if(e.flow == 0)continue; // not to consider reverse edges
                                d[e.u] = Math.min(d[e.u] , d[j] + e.cost);
                            }
                        }
                    }
                    if(check){// check for negative cycles
                        for(int j = 0; j < N; j++){
                            for(Edge e : ja[j]){
                                if(e.flow == 0)continue;
                                if(d[j] + e.cost < d[e.u]) return false;
                            }
                        }   
                    }return true;
                }

                int node[]; // present node 

                int visit[]; // 0 -> not added 1 -> not removed 2 -> removed
                int prv[], prve[]; // previous node for augmentation
                int dist[]; // min dist

                boolean simple(){
                    node = new int[N]; 
                    visit = new int[N]; 
                    prv = new int[N];
                    prve = new int[N];
                    dist = new int[N];   Arrays.fill(dist , gmax);

                    node[0] = S; dist[0] = 0;
                    int front = 1, back = 0;
                    while(front != back){
                        int u = node[back++]; int distu = dist[u];
                        if(back == N)back = 0;
                        visit[u] = 2;
                        for(int i = 0; i < ja[u].length; i++){
                            Edge e = ja[u][i];
                            if(e.flow == 0)continue;
                            int cdist = distu + e.cost; // no need of reduced cost
                            if(cdist < dist[e.u]){
                                if(visit[e.u] == 0){
                                    node[front] = e.u; 
                                    if(++front == N)front = 0;
                                }else if(visit[e.u] == 2){
                                    if(--back == -1)back += N;
                                    node[back] = e.u;
                                }
                                visit[e.u] = 1;
                                prve[e.u] = i; prv[e.u] = u; dist[e.u] = cdist;
                            }
                        }
                    }
                    return visit[T] != 0;
                }

                class pair{
                    int F; int S;
                    pair(int a, int b){F = a; S = b;}
                }

                boolean dijkstra(){
                    visit = new int[N];
                    prv = new int[N];
                    prve = new int[N];
                    dist = new int[N]; Arrays.fill(dist, gmax);
                    PriorityQueue<pair> pq = new PriorityQueue<>((A, B) -> Double.compare(A.S , B.S));

                    pq.add(new pair(S , 0)); dist[0] = 0;
                    o : while(!pq.isEmpty()){
                        pair p = pq.poll();
                        while(dist[p.F] < p.S){
                            if(pq.isEmpty()) break o; // had a better val 
                            p = pq.poll();
                        }
                        visit[p.F] = 2;
                        for(int i = 0; i < ja[p.F].length; i++){
                            Edge e = ja[p.F][i];
                            if(e.flow == 0)continue; // important
                            int cdist = p.S + (e.cost + d[p.F] - d[e.u]); // reduced cost
                            if(cdist < dist[e.u]){ 
                                if(visit[e.u] == 2) return false;
                                pq.add(new pair(e.u , cdist));
                                dist[e.u] = cdist; prv[e.u] = p.F; prve[e.u] = i;
                                visit[e.u] = 1;
                            }
                        }
                    }
                    return visit[T] != 0;
                }

                int augment(){
                    int p = T; int min = gmax;
                    while(p != 0){
                        int pp = prv[p], pe = prve[p];
                        int val = ja[pp][pe].flow;
                        min = Math.min(min , val);
                        p = pp;
                    }
