import sys
from collections import deque
import heapq

class Edge:
    def __init__(self, to, flow, cost, rev):
        self.to = to
        self.flow = flow
        self.cost = cost
        self.rev = rev

class NetworkFlow:
    def __init__(self, nodes, s, t):
        self.V = nodes
        self.src = s
        self.sink = t
        self.maxFlow = 0
        self.minCost = 0
        self.INF = 10**15
        self.graph = [[] for _ in range(self.V)]
        self.mat = None
        self.dist = None

    def addEdge(self, u, v, cap, cost):
        fwd = Edge(v, cap, cost, len(self.graph[v]))
        bkw = Edge(u, 0, -cost, len(self.graph[u]))
        self.graph[u].append(fwd)
        self.graph[v].append(bkw)

    def finalizeGraph(self):
        self.mat = [None] * self.V
        for i in range(self.V):
            self.mat[i] = self.graph[i]
            self.graph[i] = []

    def bellmanFord(self, check):
        self.dist = [10**9 // 2] * self.V
        self.dist[self.src] = 0
        for _ in range(self.V - 1):
            updated = False
            for u in range(self.V):
                if self.dist[u] == 10**9 // 2:
                    continue
                for e in self.mat[u]:
                    if e.flow > 0 and self.dist[u] + e.cost < self.dist[e.to]:
                        self.dist[e.to] = self.dist[u] + e.cost
                        updated = True
            if not updated:
                break
        if check:
            for u in range(self.V):
                if self.dist[u] == 10**9 // 2:
                    continue
                for e in self.mat[u]:
                    if e.flow > 0 and self.dist[u] + e.cost < self.dist[e.to]:
                        return False
        return True

    def spfa(self):
        distSpfa = [10**9 // 2] * self.V
        parNode = [-1] * self.V
        parEdge = [-1] * self.V
        visited = [0] * self.V
        queueSpfa = [0] * self.V
        distSpfa[self.src] = 0
        head = 0
        tail = 0
        queueSpfa[tail] = self.src
        tail += 1
        while head != tail:
            u = queueSpfa[head]
            head += 1
            if head == self.V:
                head = 0
            visited[u] = 2
            for i in range(len(self.mat[u])):
                e = self.mat[u][i]
                if e.flow == 0:
                    continue
                nd = distSpfa[u] + e.cost
                if nd < distSpfa[e.to]:
                    if visited[e.to] == 0:
                        queueSpfa[tail] = e.to
                        tail += 1
                        if tail == self.V:
                            tail = 0
                    elif visited[e.to] == 2:
                        head -= 1
                        if head == -1:
                            head += self.V
                        queueSpfa[head] = e.to
                    visited[e.to] = 1
                    parEdge[e.to] = i
                    parNode[e.to] = u
                    distSpfa[e.to] = nd
        return visited[self.sink] != 0

    def dijkstra(self):
        visited = [0] * self.V
        distSpfa = [10**9 // 2] * self.V
        parNode = [-1] * self.V
        parEdge = [-1] * self.V
        distSpfa[self.src] = 0
        pq = [(0, self.src)]
        while pq:
            cur_dist, cur_node = heapq.heappop(pq)
            while distSpfa[cur_node] < cur_dist:
                if not pq:
                    return False
                cur_dist, cur_node = heapq.heappop(pq)
            visited[cur_node] = 2
            for i in range(len(self.mat[cur_node])):
                e = self.mat[cur_node][i]
                if e.flow == 0:
                    continue
                redCost = e.cost + distSpfa[cur_node] - distSpfa[e.to]
                nd = cur_dist + redCost
                if nd < distSpfa[e.to]:
                    if visited[e.to] == 2:
                        return False
                    heapq.heappush(pq, (nd, e.to))
                    distSpfa[e.to] = nd
                    parNode[e.to] = cur_node
                    parEdge[e.to] = i
                    visited[e.to] = 1
        return visited[self.sink] != 0

    def augment(self):
        flow = 10**9
        v = self.sink
        while v != self.src:
            u = parNode[v]
            idx = parEdge[v]
            flow = min(flow, self.mat[u][idx].flow)
            v = u
        v = self.sink
        while v != self.src:
            u = parNode[v]
            idx = parEdge[v]
            self.mat[u][idx].flow -= flow
            self.mat[v][self.mat[u][idx].rev].flow += flow
            v = u
        self.maxFlow += flow
        return flow

    def computeFlow(self):
        self.bellmanFord(False)
        while self.spfa():
            if self.distSpfa[self.sink] >= 10**9 // 2 - 1:
                break
            self.minCost += self.distSpfa[self.sink] * self.augment()

    def computeFlowWithPotential(self):
        self.bellmanFord(False)
        while self.dijkstra():
            m = self.distSpfa[self.sink] + self.distSpfa[self.sink] - self.distSpfa[self.src]
            if m >= 10**9 // 2:
                break
            self.minCost += m * self.augment()
            for i in range(self.V):
                if visited[i] != 0:
                    self.distSpfa[i] += self.distSpfa[i] - self.distSpfa[self.src]

