        while self.allocated[pos] != self.NG:
            if x == self.keys[pos]:
                return True
            pos = (pos + 1) & self.mask
        return False

    def get(self, x):
        pos = self.h(x) & self.mask
        while self.allocated[pos] != self.NG:
            if x == self.keys[pos]:
                return self.allocated[pos]
            pos = (pos + 1) & self.mask
        return self.NG

    def put(self, x, v):
        pos = self.h(x) & self.mask
        while self.allocated[pos] != self.NG:
            if x == self.keys[pos]:
                oldval = self.allocated[pos]
                self.allocated[pos] = v
                return oldval
            pos = (pos + 1) & self.mask
        if self.size == self.rscale:
            self.resizeAndPut(x, v)
        else:
            self.keys[pos] = x
            self.allocated[pos] = v
        self.size += 1
        return 0

    def resizeAndPut(self, x, v):
        nscale = self.scale << 1
        nrscale = self.rscale << 1
        nmask = nscale - 1
        nallocated = [self.NG] * nscale
        nkeys = [0] * nscale
        for i in self.next(0):
            y = self.keys[i]
            pos = self.h(y) & nmask
            while nallocated[pos] != self.NG:
                pos = (pos + 1) & nmask
            nkeys[pos] = y
            nallocated[pos] = self.allocated[i]
        pos = self.h(x) & nmask
        while nallocated[pos] != self.NG:
            pos = (pos + 1) & nmask
        nkeys[pos] = x
        nallocated[pos] = v
        self.allocated = nallocated
        self.keys = nkeys
        self.scale = nscale
        self.rscale = nrscale
        self.mask = nmask

    def next(self, itr):
        while itr < self.scale and self.allocated[itr] == self.NG:
