class LongHashCounterL:
    def __init__(self):
        self.NG = 0
        self.scale = 1 << 2
        self.rscale = 1 << 1
        self.mask = self.scale - 1
        self.size = 0
        self.allocated = [self.NG] * self.scale
        self.keys = [0] * self.scale

    def h(self, x):
        x ^= x >> 33
        x *= 0xff51afd7ed558ccd
        x ^= x >> 33
        x *= 0xc4ceb9fe1a85ec53
        x ^= x >> 33
