        self.phicache = LongHashCounterL()
        self.cachePhi = True

        s = int(math.sqrt(n)) * 100
        self.cachelimit = s
        self.primes = sieveEratosthenes(s)
        self.xcums = [0] * ((s >> 6) + 1)
        self.isp = [0] * ((s >> 6) + 1)
        for p in self.primes:
            self.isp[p >> 6] |= 1 << p
        for i in range(len(self.xcums) - 1):
