        for i in range(M):
            length *= FP[i]
            c = [False] * length
            for j in range(FP[i]):
                for k in range(len(b)):
                    c[j * len(b) + k] = b[k]
            for k in range(0, length, FP[i]):
                c[k] = False
            cumps_row = [0] * (length + 1)
            for j in range(length):
                cumps_row[j + 1] = cumps_row[j] + (1 if c[j] else 0)
            self.cumps.append(cumps_row)
            FP[i] = length
            b = c

    def sqrt(self, n):
        i = max(0, int(math.sqrt(n)) - 2)
        while i * i <= n:
            i += 1
        return i - 1

    def cbrt(self, n):
        i = max(0, int(n ** (1/3)) - 2)
        while i * i * i <= n:
            i += 1
        return i - 1

    def pi(self, x):
        if x <= self.cachelimit:
            ix = int(x)
            return self.xcums[ix >> 6] + bin(self.isp[ix >> 6] << (~ix & 63)).count('1')
        if self.picache.containsKey(x):
            return self.picache.get(x)

        A = int(self.pi(self.sqrt(self.sqrt(x))))
        ret = A + self.phi(x, A) - self.P2(x, A) - self.P3(x, A) - 1
        self.picache.put(x, ret)
        return ret

    def phi(self, x, A):
        if A > 0 and A - 1 < len(self.cumps):
            fp_val = self.cumps[A-1][len(self.cumps[A-1])-1] * (x // len(self.cumps[A-1]))
            return fp_val + self.cumps[A-1][int(x % len(self.cumps[A-1]) + 1)]
        if A > 0 and x <= self.primes[A-1] * self.primes[A-1]:
            return self.pi(x) - A + 1
        code = (x << 13) | A
        if self.phicache.containsKey(code):
            return self.phicache.get(code)

        ret = x
        for i in range(A - 1, -1, -1):
            ret -= self.phi(x // self.primes[i], i)

        if self.cachePhi:
            self.phicache.put(code, ret)
        return ret

    def P2(self, x, A):
        B = int(self.pi(self.sqrt(x)))
        ret = 0
        for i in range(A, B):
            ret += self.pi(x // self.primes[i])
        ret -= (B - A) * (B + A - 1) // 2
        return ret

    def P3(self, x, A):
        C = int(self.pi(self.cbrt(x)))
        ret = 0
        for i in range(A, C):
            xi = x // self.primes[i]
            B = int(self.pi(self.sqrt(xi)))
            for j in range(i, B):
                ret += self.pi(xi // self.primes[j]) - j
        return ret

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])

    ans = 0
    ml = MeisselLehmer2(n)
    primes = sieveEratosthenes(1000000)

    for i in range(len(primes)):
        plus = ml.pi(n // primes[i]) - (i + 1)
        if plus <= 0:
