            for q in range((p * p - 3) // 2, h + 1, p):
                isnp[q >> 5] |= 1 << q

    return ret[:pos]


class MeisselLehmer2:
    def __init__(self, n):
        assert n >= 4
        self.picache = LongHashCounterL()
        self.phicache = LongHashCounterL()

        s = int(math.sqrt(n)) * 100
        self.cachelimit = s
        self.primes = sieveEratosthenes(s)
