        self.isp = [0] * ((s >> 6) + 1)
        for p in self.primes:
            self.isp[p >> 6] |= 1 << p
        for i in range(len(self.xcums) - 1):
            self.xcums[i + 1] = self.xcums[i] + bin(self.isp[i]).count('1')

        self.FP = [2, 3, 5, 7, 11, 13, 17, 19]
        self.M = len(self.FP)
        self.B = 100

        self.cumps = []
        b = [True]
        length = 1
        for i in range(self.M):
            length *= self.FP[i]
            c = [False] * length
            for j in range(self.FP[i]):
                c[j * len(b):(j + 1) * len(b)] = b[:]
            for k in range(0, length, self.FP[i]):
                c[k] = False
            cumps_row = [0] * (length + 1)
            for j in range(length):
                cumps_row[j + 1] = cumps_row[j] + (1 if c[j] else 0)
            self.cumps.append(cumps_row)
            self.FP[i] = length
            b = c[:]

    def sqrt(self, n):
        i = max(0, int(math.sqrt(n)) - 2)
        while i * i <= n:
            i += 1
        return i - 1

    def cbrt(self, n):
        i = max(0, int(math.cbrt(n)) - 2)
        while i * i * i <= n:
            i += 1
        return i - 1

