class LongHashCounterL:
    def __init__(self):
        self.scale = 1 << 2
        self.rscale = 1 << 1
        self.mask = self.scale - 1
        self.size = 0
        self.NG = 0
        self.allocated = [self.NG] * self.scale
        self.keys = [0] * self.scale

    def h(self, x):
        x ^= x >> 33
        x *= 0xff51afd7ed558ccd
        x ^= x >> 33
        x *= 0xc4ceb9fe1a85ec53
        x ^= x >> 33
        return int(x) & 0xFFFFFFFF

    def containsKey(self, x):
        pos = self.h(x) & self.mask
        while self.allocated[pos] != self.NG:
            if x == self.keys[pos]:
                return True
            pos = (pos + 1) & self.mask
        return False

    def get(self, x):
        pos = self.h(x) & self.mask
        while self.allocated[pos] != self.NG:
            if x == self.keys[pos]:
                return self.allocated[pos]
            pos = (pos + 1) & self.mask
        return self.NG

    def put(self, x, v):
        pos = self.h(x) & self.mask
        while self.allocated[pos] != self.NG:
            if x == self.keys[pos]:
                oldval = self.allocated[pos]
                self.allocated[pos] = v
                return oldval
            pos = (pos + 1) & self.mask
        if self.size == self.rscale:
            self.resizeAndPut(x, v)
        else:
            self.keys[pos] = x
            self.allocated[pos] = v
        self.size += 1
        return 0

