public class F3Variant4 {
    private static class FastInput {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        FastInput(InputStream is) { in = is; }

        private int read() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            while ((c = read()) <= ' ') if (c == -1) return Long.MIN_VALUE;
            boolean neg = false;
            if (c == '-') { neg = true; c = read(); }
            long val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + c - '0';
                c = read();
            }
            return neg ? -val : val;
