        doubleFact[0] = 1;
        for (int i = 1; i <= n; i++) {
            doubleFact[i] = mul(doubleFact[i-1], 2*i-1, MOD);
        }

        int[][] coverageCounts = new int[2*n+2][n+1];

        for (int r = 1; r <= 2*n+1; r++) {
            for (int k = 1; k <= n; k++) {
                if ((r % 2 != k % 2) && (r - 1 >= k) && (2*n+1 - r >= k)) {
                    int numerator = mul(fact[r-1], fact[2*n+1-r], MOD);
                    numerator = mul(numerator, doubleFact[(r-k-1)/2], MOD);
