                    int denominator = mul(fact[r-k-1], fact[2*n+1-r-k], MOD);
                    denominator = mul(denominator, fact[k], MOD);

                    int invPart = mul(denominator, doubleFact[n], MOD);
                    coverageCounts[r][k] = mul(numerator, modInverse(invPart, MOD), MOD);
                }
            }
        }

        int total = 0;
        for (int r = 1; r <= 2*n+1; r++) {
            for (int k = real_k; k <= n; k++) {
                total = (total + coverageCounts[r][k]) % MOD;
            }
        }

        total = mul(total, l, MOD);
        total = mul(total, modInverse(2*n+1, MOD), MOD);

