        System.out.println(result);
    }

    static int intMul(int a, int b, int mod) {
        return (int) ((1L * a * b) % mod);
    }

    static int modInv(int a, int mod) {
        int originalMod = mod;
        int x = 0, lastX = 1;
        int y = 1, lastY = 0;

        while (mod != 0) {
            int q = a / mod;
            int temp = a % mod;
            a = mod;
            mod = temp;

            temp = x;
            x = lastX - q * x;
            lastX = temp;

            temp = y;
            y = lastY - q * y;
            lastY = temp;
        }

        if (lastX < 0) lastX += originalMod;
        return lastX;
    }

