        int originalMod = mod;
        int x0 = 1, x1 = 0;
        if (mod == 1) return 0;

        while (a > 1) {
            int q = a / mod;
            int t = mod;
            mod = a % mod;
            a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }

        if (x1 < 0) x1 += originalMod;
        return x1;
    }

}

