    }

    private void doIt() throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split("\\s+");
        int n = Integer.parseInt(parts[0]);
        int k = Integer.parseInt(parts[1]);
        int lVal = Integer.parseInt(parts[2]);

        long[] fac = new long[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % MOD;
        }

        int maxDim = 2 * n + 2;
        long[][] memo = new long[2 * n + 1][maxDim];
        memo[0][0] = 1;

        for (int i = 1; i <= 2 * n; i++) {
            for (int j = 0; j <= Math.min(i, n); j++) {
                if (j > 0) memo[i][j] = (memo[i][j] + memo[i - 1][j - 1]) % MOD;
                memo[i][j] = (memo[i][j] + memo[i - 1][j + 1] * (j + 1)) % MOD;
            }
        }

        long sumResult = 0;
        for (int i = k; i <= 2 * n; i++) {
            for (int j = k; j <= n; j++) {
                sumResult = (sumResult + memo[i][j] * memo[2 * n - i][j] % MOD * fac[j]) % MOD;
            }
        }

        long d1 = memo[2 * n][0];
        long d2 = 2 * n + 1;
        long inv = modPow(d1 * d2 % MOD, MOD - 2);

        long finalAns = (long) lVal * sumResult % MOD;
        finalAns = finalAns * inv % MOD;
        System.out.println(finalAns);
    }

    private long modPow(long base, long exponent) {
        base %= MOD;
        long res = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exponent >>= 1;
        }
        return res;
    }
}

