    }

    boolean dijkstra(int s, int t) {
        Arrays.fill(dd, INF);
        dd[s] = 0; pq_add_last(s);
        while (cnt > 0) {
            int i = pq_remove_first();
            int k = kk[i] + 1;
            for (int o = ae[i]; o != 0; o = oo[o]) {
                int h_ = oh[o];
                if (cc[h_] > 0) {
                    int h = h_ >> 1;
                    int j = i ^ ii[h] ^ jj[h];
                    int d = dd[i] + ((h_ & 1) == 0 ? ww_[h] : -ww_[h]);
                    if (dd[j] > d || (dd[j] == d && kk[j] > k)) {
                        if (dd[j] == INF)
                            pq_add_last(j);
                        dd[j] = d; kk[j] = k; ff[j] = h_;
                        pq_up(j);
                    }
                }
            }
        }
        return dd[t] != INF;
    }

    int trace(int s, int t) {
        while (t != s) {
            int h_ = ff[t], h = h_ >> 1;
            cc[h_]--; cc[h_ ^ 1]++;
            t ^= ii[h] ^ jj[h];
        }
        return 1;
    }

    int edmonds_karp(int s, int t) {
        for (int h = 0; h < m_; h++) {
            int i = ii[h], j = jj[h];
            dd[j] = Math.min(dd[j], dd[i] + ww[h]);
        }
        for (int h = 0; h < m_; h++) {
            int i = ii[h], j = jj[h];
            ww_[h] = ww[h] + dd[i] - dd[j];
        }
        int f = 0;
        while (dijkstra(s, t)) {
            f += trace(s, t);
            for (int h = 0; h < m_; h++) {
                int i = ii[h], j = jj[h];
                if (dd[i] != INF && dd[j] != INF) {
                    ww_[h] += dd[i] - dd[j];
                }
            }
        }
        int cost = 0;
        for (int h = 0; h < m_; h++)
            cost += ww[h] * cc[h << 1 | 1];
        return cost;
    }

    void main() {
        int n = sc.nextInt() / 2;
        n_ = 1 + n + A + 1;
        m_ = n + n * A + A;
        init();
        String s = sc.next();
        byte[] cc = s.getBytes();
        int[] bb = new int[n * 2];
        for (int i = 0; i < n * 2; i++)
            bb[i] = sc.nextInt();
        for (int i = 0; i < n; i++)
            link_(0, 1 + i, 2, 0);
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ai = cc[i] - 'a';
            int aj = cc[j] - 'a';
            for (int a = 0; a < A; a++) {
                int b;
                if (a == ai && a == aj)
                    b = Math.max(bb[i], bb[j]);
                else if (a == ai)
                    b = bb[i];
                else if (a == aj)
                    b = bb[j];
                else
                    b = 0;
                link_(1 + i, 1 + n + a, 1, -b);
            }
        }
        int[] kk = new int[A];
        for (int i = 0; i < n * 2; i++) {
            int a = cc[i] - 'a';
            kk[a]++;
        }
        for (int a = 0; a < A; a++)
            link_(1 + n + a, n_ - 1, kk[a], 0);
        println(-edmonds_karp(0, n_ - 1));
    }
}

