        return self.capacity[edge_id]

    def push_flow(self, edge_id, flow):
        if flow == 0:
            return
        self.capacity[edge_id] -= flow

    def ensure_edge_capacity(self, size):
        if len(self.from_nodes) < size:
            new_size = max(size, 2 * len(self.from_nodes))
            self.from_nodes = self.from_nodes + [0] * (new_size - len(self.from_nodes))
            self.to_nodes = self.to_nodes + [0] * (new_size - len(self.to_nodes))
            self.next_outbound = self.next_outbound + [0] * (new_size - len(self.next_outbound))
            if self.weight is not None:
                self.weight = self.weight + [0] * (new_size - len(self.weight))
            if self.capacity is not None:
                self.capacity = self.capacity + [0] * (new_size - len(self.capacity))
            self.flags = self.flags + [0] * (new_size - len(self.flags))

    def is_sparse(self):
        return self.vertex_count == 0 or self.edge_count * 20 // self.vertex_count <= self.vertex_count


