class InputReader:
    def __init__(self, stream):
        self.stream = stream
        self.buf = []
        self.cur_char = 0
        self.num_chars = 0
        self._fill_buffer()

    def _fill_buffer(self):
        data = self.stream.read(1024)
        self.buf = list(data)
        self.num_chars = len(self.buf)
        self.cur_char = 0

    def read(self):
        if self.num_chars == -1:
            raise Exception("Input mismatch")
        if self.cur_char >= self.num_chars:
            self.cur_char = 0
            self._fill_buffer()
            if self.num_chars <= 0:
                return -1
        result = self.buf[self.cur_char]
        self.cur_char += 1
        return result

    def next_int(self):
        c = self.read()
        while self._is_space_char(c):
            c = self.read()
        sgn = 1
        if c == ord('-'):
            sgn = -1
            c = self.read()
        res = 0
        while not self._is_space_char(c):
            if c < ord('0') or c > ord('9'):
                raise Exception("Input mismatch")
            res *= 10
            res += c - ord('0')
            c = self.read()
        return res * sgn

    def next_string(self):
        c = self.read()
        while self._is_space_char(c):
            c = self.read()
        res = []
        while not self._is_space_char(c):
            if 0 <= c <= 0x10FFFF:
                res.append(chr(c))
            c = self.read()
        return ''.join(res)

    def _is_space_char(self, c):
        return c in (ord(' '), ord('\n'), ord('\r'), ord('\t'), -1)


class OutputWriter:
    def __init__(self, stream):
        self.writer = stream

    def println(self, value):
        self.writer.write(str(value) + '\n')
        self.writer.flush()


