            if self.last_edge[self.destination] == -1:
                return Pair(cost, flow)
            for i in range(len(self.dijkstra_result)):
                if self.dijkstra_result[i] != float('inf'):
                    self.phi[i] += self.dijkstra_result[i]
            vertex = self.destination
            current_flow = max_flow
            current_cost = 0
            while vertex != self.source:
                edge_id = self.last_edge[vertex]
                current_flow = min(current_flow, self.graph.capacity(edge_id))
                current_cost += self.graph.weight(edge_id)
                vertex = self.graph.source(edge_id)
            max_flow -= current_flow
            cost += current_cost * current_flow
            flow += current_flow
            vertex = self.destination
            while vertex != self.source:
                edge_id = self.last_edge[vertex]
                self.graph.push_flow(edge_id, current_flow)
                vertex = self.graph.source(edge_id)
        return Pair(cost, flow)

    def dijkstra_algorithm(self):
        self.dijkstra_result = [float('inf')] * self.vertex_count
        self.last_edge = [-1] * self.vertex_count
        self.dijkstra_result[self.source] = 0
        self.heap.add(self.source)
        while not self.heap.is_empty():
            current = self.heap.poll()
            edge_id = self.graph.first_outbound[current]
            while edge_id != -1:
                if self.graph.capacity(edge_id) != 0:
                    next_node = self.graph.destination(edge_id)
                    total = self.graph.weight(edge_id) - self.phi[next_node] + self.phi[current] + self.dijkstra_result[current]
                    if self.dijkstra_result[next_node] > total:
                        self.dijkstra_result[next_node] = total
                        if self.heap.get_index(next_node) == -1:
                            self.heap.add(next_node)
                        else:
                            self.heap.shift_up(self.heap.get_index(next_node))
                        self.last_edge[next_node] = edge_id
                edge_id = self.graph.next_outbound[edge_id]

    def dijkstra_algorithm_full(self):
        self.visit_index += 1
        self.dijkstra_result = [float('inf')] * self.vertex_count
        self.last_edge[self.destination] = -1
        self.dijkstra_result[self.source] = 0
        for _ in range(self.vertex_count):
            index = -1
            length = float('inf')
            for j in range(self.vertex_count):
                if self.visited[j] != self.visit_index and self.dijkstra_result[j] < length:
                    length = self.dijkstra_result[j]
                    index = j
            if index == -1:
                return
            self.visited[index] = self.visit_index
            edge_id = self.graph.first_outbound[index]
            while edge_id != -1:
                if self.graph.capacity(edge_id) != 0:
                    next_node = self.graph.destination(edge_id)
                    if self.visited[next_node] != self.visit_index:
                        total = self.graph.weight(edge_id) - self.phi[next_node] + self.phi[index] + length
                        if self.dijkstra_result[next_node] > total:
                            self.dijkstra_result[next_node] = total
                            self.last_edge[next_node] = edge_id
                edge_id = self.graph.next_outbound[edge_id]


class OutputWriter:
    def __init__(self, output_stream):
        self.writer = output_stream

    def close(self):
        pass

    def println(self, value):
        self.writer.write(str(value) + '\n')


class InputReader:
    def __init__(self, input_stream):
        self.stream = input_stream
        self.buf = []
        self.cur_char = 0
        self.num_chars = 0
        self._fill_buffer()

    def _fill_buffer(self):
        data = self.stream.read(1024)
        if not data:
            self.num_chars = -1
            return
        self.buf = list(data)
        self.num_chars = len(self.buf)
        self.cur_char = 0

    def read(self):
        if self.num_chars == -1:
            raise Exception("Input mismatch")
        if self.cur_char >= self.num_chars:
            self.cur_char = 0
            self._fill_buffer()
            if self.num_chars <= 0:
                return -1
        result = self.buf[self.cur_char]
        self.cur_char += 1
        return result

    def next_int(self):
        c = self.read()
        while self._is_space_char(c):
            c = self.read()
        sgn = 1
        if c == ord('-'):
            sgn = -1
            c = self.read()
        res = 0
        while not self._is_space_char(c):
            if c < ord('0') or c > ord('9'):
                raise Exception("Input mismatch")
            res *= 10
            res += c - ord('0')
            c = self.read()
        return res * sgn

    def next_string(self):
        c = self.read()
        while self._is_space_char(c):
            c = self.read()
        res = []
        while not self._is_space_char(c):
            if 0 <= c <= 0x10FFFF:
                res.append(chr(c))
            c = self.read()
        return ''.join(res)

    def _is_space_char(self, c):
        return c in (ord(' '), ord('\n'), ord('\r'), ord('\t'), -1)


class Heap:
    def __init__(self, max_element, comparator):
        self.comparator = comparator
        self.size = 0
        self.elements = []
        self.at = [-1] * max_element

    def is_empty(self):
        return self.size == 0

    def add(self, element):
        if len(self.elements) < self.size + 1:
            self.elements.append(element)
        else:
            self.elements[self.size] = element
        self.at[element] = self.size
        self.shift_up(self.size)
        self.size += 1

    def shift_up(self, index):
        value = self.elements[index]
        while index != 0:
            parent = (index - 1) // 2
            parent_value = self.elements[parent]
            if self.comparator(parent_value, value) <= 0:
                self.elements[index] = value
                self.at[value] = index
                return
            self.elements[index] = parent_value
            self.at[parent_value] = index
            index = parent
        self.elements[0] = value
        self.at[value] = 0

    def shift_down(self, index):
        while True:
            child = (index << 1) + 1
            if child >= self.size:
                return
            if child + 1 < self.size and self.comparator(self.elements[child], self.elements[child + 1]) > 0:
                child += 1
            if self.comparator(self.elements[index], self.elements[child]) <= 0:
                return
            self.swap(index, child)
            index = child

    def get_index(self, element):
        return self.at[element]

    def swap(self, first, second):
        temp = self.elements[first]
        self.elements[first] = self.elements[second]
        self.elements[second] = temp
        self.at[self.elements[first]] = first
        self.at[self.elements[second]] = second

    def poll(self):
        if self.is_empty():
            raise IndexError("Heap is empty")
        result = self.elements[0]
        self.at[result] = -1
        if self.size == 1:
            self.size = 0
            return result
        self.elements[0] = self.elements[self.size - 1]
        self.at[self.elements[0]] = 0
        self.size -= 1
        self.shift_down(0)
        return result


def main():
    reader = InputReader(sys.stdin.buffer)
    writer = OutputWriter(sys.stdout)

    n = reader.next_int()
    s = reader.next_string()
    a = [0] * n
    cnt = [0] * 26
    for i in range(n):
        a[i] = reader.next_int()
        cnt[ord(s[i]) - ord('a')] += 1

    g = Graph(n + 100)
    src = n + 100 - 2
    tgt = src + 1

    for i in range(n // 2):
        g.add_flow_weighted_edge(i, tgt, 0, 2)

    for i in range(26):
        g.add_flow_weighted_edge(src, i + n, 0, cnt[i])
        for j in range(n // 2):
            if s[j] == s[n - j - 1]:
                w = 0
                if s[j] == chr(i + ord('a')):
                    w = -max(a[j], a[n - j - 1])
                g.add_flow_weighted_edge(i + n, j, w, 1)
            else:
                w = 0
                if s[j] == chr(i + ord('a')):
                    w -= a[j]
                if s[n - j - 1] == chr(i + ord('a')):
                    w -= a[n - j - 1]
                g.add_flow_weighted_edge(i + n, j, w, 1)

    mcmf = MinCostFlow(g, src, tgt, True)
    result = mcmf.min_cost_max_flow()
    writer.println(-result.first)

