    }

    private void run() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String s = br.readLine();
        int[] b = Arrays.stream(br.readLine().split("\\s+")).mapToInt(Integer::parseInt).toArray();
        char[] res = s.toCharArray();

        Set<Integer> waiting = new HashSet<>();
        for (int i = 0; i < n / 2; i++) {
            if (res[i] == res[n - i - 1]) {
                if (waiting.isEmpty()) {
                    waiting.add(i);
                } else {
                    boolean matched = false;
                    for (int j : waiting) {
                        if (res[j] != res[i]) {
                            int idx1 = b[j] < b[n - j - 1] ? j : n - j - 1;
                            int idx2 = b[i] < b[n - i - 1] ? i : n - i - 1;
                            swap(res, idx1, idx2);
                            b[idx1] = 0;
                            b[idx2] = 0;
                            waiting.remove(j);
                            matched = true;
                            break;
                        }
                    }
                    if (!matched) waiting.add(i);
                }
            }
        }

        Map<Integer, Set<Integer>> groups = new TreeMap<>();
        groups.put(0, new HashSet<>());
        for (int i = 0; i < n; i++) {
            groups.computeIfAbsent(b[i], k -> new HashSet<>()).add(i);
        }

        for (int i = 0; i < n / 2; i++) {
            if (res[i] == res[n - i - 1]) {
                boolean done = false;
                int target = b[i] < b[n - i - 1] ? i : n - i - 1;

                for (Set<Integer> group : groups.values()) {
                    for (int j : group) {
                        if (j == i || j == target || res[target] == res[j] || res[target] == res[n - j - 1]) continue;

                        swap(res, target, j);
                        b[target] = 0;
                        b[j] = 0;

                        groups.get(0).add(target);
                        groups.get(0).add(j);

                        done = true;
                        break;
                    }
                    if (done) break;
                }

                if (res[i] == res[n - i - 1]) System.out.println("alarma");
            }
        }

        for (int i = 0; i < n / 2; i++) {
            if (res[i] == res[n - i - 1]) {
                System.out.println("FFFF");
            }
        }

        int total = 0;
        for (int cost : b) total += cost;
        System.out.println(total);
    }

    private static void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

