	void pq_up(int u) {
		int i, j, v;
		for (i = iq[u]; (j = i / 2) > 0 && less(u, v = pq[j]); i = j)
			pq[iq[v] = i] = v;
		pq[iq[u] = i] = u;
	}
	void pq_dn(int u) {
		int i, j, v;
		for (i = iq[u]; (j = i2(i)) > 0 && less(v = pq[j], u); i = j)
			pq[iq[v] = i] = v;
		pq[iq[u] = i] = u;
	}
	void pq_add_last(int u) {
		pq[iq[u] = ++cnt] = u;
	}
	int pq_remove_first() {
		int u = pq[1], v = pq[cnt--];
		if (v != u) {
			iq[v] = 1; pq_dn(v);
		}
		iq[u] = 0;
		return u;
	}
	boolean dijkstra(int s, int t) {
		Arrays.fill(pi, INF);
		pi[s] = 0; pq_add_last(s);
		while (cnt > 0) {
			int i = pq_remove_first();
			int d = dd[i] + 1;
			for (int o = ae[i]; o != 0; o = oo[o]) {
				int h_ = oh[o];
				if (cc[h_] > 0) {
					int h = h_ >> 1;
					int j = i ^ ii[h] ^ jj[h];
					int p = pi[i] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
					if (pi[j] > p || pi[j] == p && dd[j] > d) {
						if (pi[j] == INF)
							pq_add_last(j);
						pi[j] = p; dd[j] = d; ff[j] = h_;
						pq_up(j);
					}
				}
			}
		}
		return pi[t] != INF;
	}
	int trace(int s, int t) {
		while (t != s) {
			int h_ = ff[t], h = h_ >> 1;
			cc[h_]--; cc[h_ ^ 1]++;
			t ^= ii[h] ^ jj[h];
		}
		return 1;
	}
	int edmonds_karp(int s, int t) {
		for (int h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];
			pi[j] = Math.min(pi[j], pi[i] + cost[h]);
		}
		for (int h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];
			cost_[h] = cost[h] + pi[i] - pi[j];
		}
		int f = 0;
		while (dijkstra(s, t)) {
			f += trace(s, t);
			for (int h = 0; h < m_; h++) {
				int i = ii[h], j = jj[h];
				if (pi[i] != INF && pi[j] != INF) {
					// pi[j] <= pi[i] + cost_[h]
					// cost_[h] + pi[i] - pi[j] >= 0
					cost_[h] += pi[i] - pi[j];
				}
			}
		}
		int ans = 0;
		for (int h = 0; h < m_; h++)
			ans += cc[h << 1 | 1] * cost[h];
		return ans;
	}
	void main() {
		int n = sc.nextInt() / 2;
		n_ = 1 + n + A + 1;
		m_ = n + n * A + A;
		init();
		byte[] cc = sc.next().getBytes();
		int[] bb = new int[n * 2];
		for (int i = 0; i < n * 2; i++)
			bb[i] = sc.nextInt();
		for (int i = 0; i < n; i++)
			link_(0, 1 + i, 2, 0);
		for (int i = 0; i < n; i++) {
			int j = n * 2 - 1 - i;
			int ai = cc[i] - 'a';
			int aj = cc[j] - 'a';
			for (int a = 0; a < A; a++) {
				int b;
				if (a == ai && a == aj)
					b = Math.max(bb[i], bb[j]);
				else if (a == ai)
					b = bb[i];
				else if (a == aj)
					b = bb[j];
				else
					b = 0;
				link_(1 + i, 1 + n + a, 1, -b);
			}
		}
		int[] kk = new int[A];
		for (int i = 0; i < n * 2; i++) {
			int a = cc[i] - 'a';
			kk[a]++;
		}
		for (int a = 0; a < A; a++)
			link_(1 + n + a, n_ - 1, kk[a], 0);
		println(-edmonds_karp(0, n_ - 1));
	}
}

import java.io.*;
import java.util.*;

public class CF884F extends PrintWriter {
    CF884F() { super(System.out, true); }
    Scanner sc = new Scanner(System.in);

    public static void main(String[] args) {
        new CF884F().run();
    }

    void run() {
        solve();
        flush();
    }

    static final int ALPHABET_SIZE = 26;
    static final int INFINITY = 0x3f3f3f3f;

    // Edge list structures
    int[] nextEdge, toVertex;
    int edgeCount = 1;

    int[] fromNode, toNode, capacity, origCost, reducedCost;
    int numEdges;

    int[] adjacency, predecessor, dist, flowEdge;
    int numVertices;

    // Priority queue for Dijkstra
    int[] heap, vertexPos;
    int heapSize;

    void initialize() {
        nextEdge = new int[1 + numEdges * 2];
        toVertex = new int[1 + numEdges * 2];

        fromNode = new int[numEdges];
        toNode = new int[numEdges];
        capacity = new int[numEdges << 1];
        origCost = new int[numEdges];
        reducedCost = new int[numEdges];

        adjacency = new int[numVertices];
        predecessor = new int[numVertices];
        dist = new int[numVertices];
        flowEdge = new int[numVertices];

        heap = new int[1 + numVertices];
        vertexPos = new int[numVertices];

        numEdges = 0;
    }

    void addEdge(int u, int v, int cap, int cost) {
        int edgeIndex = numEdges++;
        fromNode[edgeIndex] = u;
        toNode[edgeIndex] = v;
        capacity[edgeIndex << 1] = cap;
        origCost[edgeIndex] = cost;

        adjacency[u] = link(adjacency[u], edgeIndex << 1);
        adjacency[v] = link(adjacency[v], edgeIndex << 1 | 1);
    }

    int link(int oldHead, int newEdge) {
        nextEdge[edgeCount] = oldHead;
        toVertex[edgeCount] = newEdge;
        return edgeCount++;
    }

    boolean compareNodes(int u, int v) {
        return predecessor[u] < predecessor[v] || 
               (predecessor[u] == predecessor[v] && dist[u] < dist[v]);
    }

    int getMinChild(int i) {
        int left = i << 1;
        if (left > heapSize) return 0;
        int right = left + 1;
        if (right > heapSize) return left;
        return compareNodes(heap[right], heap[left]) ? right : left;
    }

    void heapUp(int node) {
        int index = vertexPos[node];
        while (index > 1) {
            int parent = index >> 1;
            if (compareNodes(node, heap[parent])) {
                int parentNode = heap[parent];
                heap[vertexPos[parentNode] = index] = parentNode;
                index = parent;
            } else break;
        }
        heap[vertexPos[node] = index] = node;
    }

    void heapDown(int node) {
        int index = vertexPos[node];
        while (true) {
            int child = getMinChild(index);
            if (child == 0 || compareNodes(heap[child], node)) break;
            int childNode = heap[child];
            heap[vertexPos[childNode] = index] = childNode;
            index = child;
        }
        heap[vertexPos[node] = index] = node;
    }

    void pushToHeap(int node) {
        heap[vertexPos[node] = ++heapSize] = node;
    }

    int popFromHeap() {
        int node = heap[1];
        int last = heap[heapSize--];
        if (last != node) {
            vertexPos[last] = 1;
            heapDown(last);
        }
        vertexPos[node] = 0;
        return node;
    }

    boolean dijkstra(int source, int sink) {
        Arrays.fill(predecessor, INFINITY);
        predecessor[source] = 0;
        heapSize = 0;
        pushToHeap(source);

        while (heapSize > 0) {
            int current = popFromHeap();
            int currentDist = dist[current] + 1;

            for (int e = adjacency[current]; e != 0; e = nextEdge[e]) {
                int edgeIdx = toVertex[e];
                if (capacity[edgeIdx] > 0) {
                    int revEdge = edgeIdx ^ 1;
                    int neighbor = current ^ fromNode[edgeIdx >> 1] ^ toNode[edgeIdx >> 1];
                    int newCost = predecessor[current] + ((edgeIdx & 1) == 0 ? reducedCost[edgeIdx >> 1] : -reducedCost[edgeIdx >> 1]);

                    if (predecessor[neighbor] > newCost || 
                        (predecessor[neighbor] == newCost && dist[neighbor] > currentDist)) {
                        if (predecessor[neighbor] == INFINITY) {
                            pushToHeap(neighbor);
                        }
                        predecessor[neighbor] = newCost;
                        dist[neighbor] = currentDist;
                        flowEdge[neighbor] = edgeIdx;
                        heapUp(neighbor);
                    }
                }
            }
        }
        return predecessor[sink] != INFINITY;
    }

    int augmentPath(int source, int sink) {
        while (sink != source) {
            int edgeIdx = flowEdge[sink];
            int revEdge = edgeIdx ^ 1;
            capacity[edgeIdx]--;
            capacity[revEdge]++;
            sink ^= fromNode[edgeIdx >> 1] ^ toNode[edgeIdx >> 1];
        }
        return 1;
    }

    int minCostMaxFlow(int source, int sink) {
        // Johnson's potential initialization
        for (int e = 0; e < numEdges; e++) {
            int u = fromNode[e], v = toNode[e];
            predecessor[v] = Math.min(predecessor[v], predecessor[u] + origCost[e]);
        }

        for (int e = 0; e < numEdges; e++) {
            int u = fromNode[e], v = toNode[e];
            reducedCost[e] = origCost[e] + predecessor[u] - predecessor[v];
        }

        int totalFlow = 0;
        while (dijkstra(source, sink)) {
            totalFlow += augmentPath(source, sink);

            for (int e = 0; e < numEdges; e++) {
                int u = fromNode[e], v = toNode[e];
                if (predecessor[u] != INFINITY && predecessor[v] != INFINITY) {
                    reducedCost[e] += predecessor[u] - predecessor[v];
                }
            }
        }

        int totalCost = 0;
        for (int e = 0; e < numEdges; e++) {
            totalCost += capacity[e << 1 | 1] * origCost[e];
        }
        return totalCost;
    }

    void solve() {
        int n = sc.nextInt() / 2;
        numVertices = 1 + n + ALPHABET_SIZE + 1;
        numEdges = n + n * ALPHABET_SIZE + ALPHABET_SIZE;
        initialize();

        byte[] chars = sc.next().getBytes();
        int[] values = new int[n * 2];
        for (int i = 0; i < n * 2; i++) {
            values[i] = sc.nextInt();
        }

        // Connect source to left positions
        for (int i = 0; i < n; i++) {
            addEdge(0, 1 + i, 2, 0);
        }

        // Connect positions to letters
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int charI = chars[i] - 'a';
            int charJ = chars[j] - 'a';

            for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
                int val;
                if (letter == charI && letter == charJ) {
                    val = Math.max(values[i], values[j]);
                } else if (letter == charI) {
                    val = values[i];
                } else if (letter == charJ) {
                    val = values[j];
                } else {
                    val = 0;
                }
                addEdge(1 + i, 1 + n + letter, 1, -val);
            }
        }

        int[] letterCounts = new int[ALPHABET_SIZE];
        for (int i = 0; i < n * 2; i++) {
            int ch = chars[i] - 'a';
            letterCounts[ch]++;
        }

        // Connect letters to sink
        for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
            addEdge(1 + n + letter, numVertices - 1, letterCounts[letter], 0);
        }

        println(-minCostMaxFlow(0, numVertices - 1));
    }
}

import java.io.*;
import java.util.*;

public class CF884F extends PrintWriter {
    public static void main(String[] args) {
        new CF884F().process();
    }

    CF884F() { super(System.out, true); }
    Scanner sc = new Scanner(System.in);

    static final int ALPHABET_SIZE = 26;
    static final int INF = 0x3f3f3f3f;

    static class Edge {
        int to, capacity, cost, rev;
        Edge(int t, int c, int co, int r) {
            to = t; capacity = c; cost = co; rev = r;
        }
    }

    List<List<Edge>> graph;
    int numVertices;

    void createGraph() {
        graph = new ArrayList<>();
        for (int i = 0; i < numVertices; i++) {
            graph.add(new ArrayList<>());
        }
    }

    void addBiDirectionalEdge(int u, int v, int cap, int cost) {
        graph.get(u).add(new Edge(v, cap, cost, graph.get(v).size()));
        graph.get(v).add(new Edge(u, 0, -cost, graph.get(u).size() - 1));
    }

    boolean spfa(int source, int sink, int[] dist, int[] prevNode, int[] prevEdge) {
        Arrays.fill(dist, INF);
        dist[source] = 0;
        boolean[] inQueue = new boolean[numVertices];
        Queue<Integer> q = new LinkedList<>();
        q.offer(source);
        inQueue[source] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            inQueue[u] = false;

            for (int i = 0; i < graph.get(u).size(); i++) {
                Edge e = graph.get(u).get(i);
                if (e.capacity > 0 && dist[u] + e.cost < dist[e.to]) {
                    dist[e.to] = dist[u] + e.cost;
                    prevNode[e.to] = u;
                    prevEdge[e.to] = i;
                    if (!inQueue[e.to]) {
                        q.offer(e.to);
                        inQueue[e.to] = true;
                    }
                }
            }
        }
        return dist[sink] != INF;
    }

    int minCostFlow(int source, int sink) {
        int[] dist = new int[numVertices];
        int[] prevNode = new int[numVertices];
        int[] prevEdge = new int[numVertices];
        int flow = 0;
        int cost = 0;

        while (spfa(source, sink, dist, prevNode, prevEdge)) {
            int f = INF;
            for (int v = sink; v != source; v = prevNode[v]) {
                Edge e = graph.get(prevNode[v]).get(prevEdge[v]);
                f = Math.min(f, e.capacity);
            }

            for (int v = sink; v != source; v = prevNode[v]) {
                Edge e = graph.get(prevNode[v]).get(prevEdge[v]);
                e.capacity -= f;
                graph.get(v).get(e.rev).capacity += f;
            }

            flow += f;
            cost += f * dist[sink];
        }

        return cost;
    }

    void process() {
        int n = sc.nextInt() / 2;
        numVertices = 1 + n + ALPHABET_SIZE + 1;

        createGraph();

        byte[] chars = sc.next().getBytes();
        int[] values = new int[n * 2];
        for (int i = 0; i < n * 2; i++) {
            values[i] = sc.nextInt();
        }

        // Source to positions
        for (int i = 0; i < n; i++) {
            addBiDirectionalEdge(0, 1 + i, 2, 0);
        }

        // Positions to letters
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int charI = chars[i] - 'a';
            int charJ = chars[j] - 'a';

            for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
                int val;
                if (letter == charI && letter == charJ) {
                    val = Math.max(values[i], values[j]);
                } else if (letter == charI) {
                    val = values[i];
                } else if (letter == charJ) {
                    val = values[j];
                } else {
                    val = 0;
                }
                addBiDirectionalEdge(1 + i, 1 + n + letter, 1, -val);
            }
        }

        int[] letterCounts = new int[ALPHABET_SIZE];
        for (int i = 0; i < n * 2; i++) {
            int ch = chars[i] - 'a';
            letterCounts[ch]++;
        }

        // Letters to sink
        for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
            addBiDirectionalEdge(1 + n + letter, numVertices - 1, letterCounts[letter], 0);
        }

        int result = minCostFlow(0, numVertices - 1);
        println(-result);
    }
}

import java.io.*;
import java.util.*;

public class CF884F extends PrintWriter {
    public static void main(String[] args) {
        new CF884F().execute();
    }

    CF884F() { super(System.out, true); }
    Scanner sc = new Scanner(System.in);

    static final int ALPHABET_SIZE = 26;
    static final int INF = 0x3f3f3f3f;

    int[] head, to, next, cap, cost, rev;
    int edgeIndex;

    void setup(int nodes) {
        head = new int[nodes];
        Arrays.fill(head, -1);
        to = new int[10000];
        next = new int[10000];
        cap = new int[10000];
        cost = new int[10000];
        rev = new int[10000];
        edgeIndex = 0;
    }

    void connect(int u, int v, int c, int co) {
        to[edgeIndex] = v;
        cap[edgeIndex] = c;
        cost[edgeIndex] = co;
        next[edgeIndex] = head[u];
        rev[edgeIndex] = edgeIndex ^ 1;
        head[u] = edgeIndex++;

        to[edgeIndex] = u;
        cap[edgeIndex] = 0;
        cost[edgeIndex] = -co;
        next[edgeIndex] = head[v];
        rev[edgeIndex] = edgeIndex ^ 1;
        head[v] = edgeIndex++;
    }

    int minCostFlow(int src, int dst) {
        int nodes = head.length;
        int[] dist = new int[nodes];
        int[] prevv = new int[nodes];
        int[] preve = new int[nodes];
        int totalFlow = 0;
        int totalCost = 0;

        while (true) {
            Arrays.fill(dist, INF);
            dist[src] = 0;
            boolean[] visited = new boolean[nodes];
            PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
            pq.offer(new int[]{0, src});

            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int d = cur[0], u = cur[1];
                if (visited[u]) continue;
                visited[u] = true;

                for (int e = head[u]; e != -1; e = next[e]) {
                    if (cap[e] > 0 && dist[u] + cost[e] < dist[to[e]]) {
                        dist[to[e]] = dist[u] + cost[e];
                        prevv[to[e]] = u;
                        preve[to[e]] = e;
                        pq.offer(new int[]{dist[to[e]], to[e]});
                    }
                }
            }

            if (dist[dst] == INF) break;

            int f = INF;
            for (int v = dst; v != src; v = prevv[v]) {
                f = Math.min(f, cap[preve[v]]);
            }

            for (int v = dst; v != src; v = prevv[v]) {
                int e = preve[v];
                cap[e] -= f;
                cap[e ^ 1] += f;
                totalCost += f * cost[e];
            }
            totalFlow += f;
        }

        return totalCost;
    }

    void execute() {
        int n = sc.nextInt() / 2;
        int totalNodes = 1 + n + ALPHABET_SIZE + 1;
        setup(totalNodes);

        byte[] chars = sc.next().getBytes();
        int[] values = new int[n * 2];
        for (int i = 0; i < n * 2; i++) {
            values[i] = sc.nextInt();
        }

        for (int i = 0; i < n; i++) {
            connect(0, 1 + i, 2, 0);
        }

        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ci = chars[i] - 'a';
            int cj = chars[j] - 'a';

            for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
                int val;
                if (letter == ci && letter == cj) {
                    val = Math.max(values[i], values[j]);
                } else if (letter == ci) {
                    val = values[i];
                } else if (letter == cj) {
                    val = values[j];
                } else {
                    val = 0;
                }
                connect(1 + i, 1 + n + letter, 1, -val);
            }
        }

        int[] letterCounts = new int[ALPHABET_SIZE];
        for (int i = 0; i < n * 2; i++) {
            int ch = chars[i] - 'a';
            letterCounts[ch]++;
        }

        for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
            connect(1 + n + letter, totalNodes - 1, letterCounts[letter], 0);
        }

        println(-minCostFlow(0, totalNodes - 1));
    }
}

import java.io.*;
import java.util.*;

public class CF884F {
    public static void main(String[] args) {
        new CF884F().start();
    }

    Scanner sc = new Scanner(System.in);
    PrintWriter out = new PrintWriter(System.out, true);

    static final int ALPHABET_SIZE = 26;
    static final int INF = 0x3f3f3f3f;

    void start() {
        solve();
        out.close();
    }

    void solve() {
        int n = sc.nextInt() / 2;
        int totalNodes = 1 + n + ALPHABET_SIZE + 1;

        int[][] adj = new int[totalNodes][];
        int[][] to = new int[totalNodes * ALPHABET_SIZE * 2][];
        int edgeCount = 0;

        // Initialize adjacency lists
        for (int i = 0; i < totalNodes; i++) {
            adj[i] = new int[ALPHABET_SIZE * 2 + 5];
            Arrays.fill(adj[i], -1);
        }

        byte[] chars = sc.next().getBytes();
        int[] values = new int[n * 2];
        for (int i = 0; i < n * 2; i++) {
            values[i] = sc.nextInt();
        }

        // Connect source to positions
        for (int i = 0; i < n; i++) {
            addEdge(adj, to, edgeCount++, 0, 1 + i, 2, 0);
        }

        // Connect positions to letters
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ci = chars[i] - 'a';
            int cj = chars[j] - 'a';

            for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
                int val;
                if (letter == ci && letter == cj) {
                    val = Math.max(values[i], values[j]);
                } else if (letter == ci) {
                    val = values[i];
                } else if (letter == cj) {
                    val = values[j];
                } else {
                    val = 0;
                }
                addEdge(adj, to, edgeCount++, 1 + i, 1 + n + letter, 1, -val);
            }
        }

        int[] letterCounts = new int[ALPHABET_SIZE];
        for (int i = 0; i < n * 2; i++) {
            int ch = chars[i] - 'a';
            letterCounts[ch]++;
        }

        for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
            addEdge(adj, to, edgeCount++, 1 + n + letter, totalNodes - 1, letterCounts[letter], 0);
        }

        int result = minCostMaxFlow(adj, to, edgeCount, totalNodes, 0, totalNodes - 1);
        out.println(-result);
    }

    void addEdge(int[][] adj, int[][] to, int idx, int u, int v, int cap, int cost) {
        int edgeIdx = idx * 2;
        to[edgeIdx] = new int[]{v, cap, cost, adj[u][0]++};
        if (adj[u].length > adj[u][0]) {
            adj[u][adj[u][0]] = edgeIdx;
        }

        edgeIdx++;
        to[edgeIdx] = new int[]{u, 0, -cost, adj[v][0]++};
        if (adj[v].length > adj[v][0]) {
            adj[v][adj[v][0]] = edgeIdx;
        }
    }

    int minCostMaxFlow(int[][] adj, int[][] to, int edgeCount, int totalNodes, int src, int dst) {
        int[] potential = new int[totalNodes];
        Arrays.fill(potential, INF);
        potential[src] = 0;

        // Bellman-Ford for initial potential
        for (int iter = 0; iter < totalNodes; iter++) {
            for (int u = 0; u < totalNodes; u++) {
                if (potential[u] == INF) continue;
                for (int i = 1; i <= adj[u][0]; i++) {
                    int e = adj[u][i];
