        this.vNum = vNum;
        this.src = src;
        this.sink = sink;
        res = new int[vNum][vNum];
        cost = new int[vNum][vNum];
        costGraph = new ArrayList<>();
        d = new int[vNum];
        p = new int[vNum];
    }

