            self.res[prev][cur] -= cur_flow
            self.res[cur][prev] += cur_flow
            path_cost += self.cost[prev][cur] * cur_flow
            cur = prev

        return [cur_flow, path_cost]

    def getMinCostMaxFlow(self):
        flow = 0
        total_cost = 0

        while True:
            # Reset path array for Bellman-Ford
            INF = float('inf')
            d = [INF] * self.vNum
            self.p = [-1] * self.vNum

            d[self.src] = 0
            changed = False

            # Bellman-Ford algorithm
