		// int n = nextInt();
		// int k = nextInt();
		// int s = nextInt() - 1;
		// long t = nextLong();
		while (t % n != 0) {
			int delta = (int) ((s < k ? 1 : -1) * (t % n));
			s = (s + n + delta) % n;
			t--;
		}

		t /= n;

		long[] when = new long[n];
		Arrays.fill(when, -1);

		for (long left = t; left > 0; left--) {
			if (when[s] != -1) {
				long period = when[s] - left;

				for (int i = 0; i < n; i++) {
					if (when[i] != -1 && when[i] <= when[s]
							&& when[i] % period == 0) {
						// out.println(i + 1);
						return i;
					}
				}

				throw new AssertionError();

			}
			when[s] = left;

			for (int i = n - 1; i > 0; i--) {
				if (s < k) {
					s += i;
					if (s >= n) {
						s -= n;
					}
				} else {
					s -= i;
					if (s < 0) {
						s += n;
					}
				}
			}

		}

		// out.println(s + 1);
		return s;

	}

	int go(int n, int m) {
