class OutputPrinter:
    def __init__(self, os):
        self.pw = sys.stdout

    def println(self, val):
        self.pw.write(str(val) + '\n')

    def close(self):
        pass

class CardShuffleProblem:
    def __init__(self):
        self.fact = None
        self.invFact = None

    def run(self, testNo, in_parser, out_printer):
        n = in_parser.nextInt()
        m = in_parser.nextInt()
        self.init(n + m + 10)

        totalPhases = 1
        term = 1
        i = 0
        while term != 0:
            term = self.mul(term, self.mul(n - i, self.inv(n + m - i)))
            totalPhases = self.add(totalPhases, term)
            i += 1

        answer = 0
        for k in range(1, n + 1):
            phases = self.mul(m + k, self.inv(k))
            expVal = self.mul(phases, totalPhases)
            contrib = self.mul(self.nCr(n, k), expVal)

            if k % 2 == 1:
                answer = self.add(answer, contrib)
            else:
                answer = self.sub(answer, contrib)

        out_printer.println(answer)

    def init(self, limit):
        self.fact = [0] * limit
        self.invFact = [0] * limit
        self.fact[0] = 1
        for i in range(1, limit):
            self.fact[i] = (self.fact[i - 1] * i) % MOD
        self.invFact[limit - 1] = self.pow(self.fact[limit - 1], MOD - 2)
        for i in range(limit - 2, -1, -1):
            self.invFact[i] = (self.invFact[i + 1] * (i + 1)) % MOD

    def nCr(self, n, r):
        if r < 0 or r > n:
            return 0
        return self.fact[n] * self.invFact[r] % MOD * self.invFact[n - r] % MOD

    def inv(self, x):
        return self.pow(x, MOD - 2)

    def add(self, a, b):
        a += b
        return a - MOD if a >= MOD else a

    def sub(self, a, b):
        a -= b
        return a + MOD if a < 0 else a

    def mul(self, a, b):
        return (a * b) % MOD

    def pow(self, base, exp):
        res = 1
        base %= MOD
        while exp > 0:
            if exp & 1:
                res = (res * base) % MOD
            base = (base * base) % MOD
            exp >>= 1
        return res

