class Mod998:
    def __init__(self):
        self.modulus_val = 998244353
        self.factorial = [1]
        self.inv_factorial = [1]

    def fact(self, n):
        while len(self.factorial) <= n:
            self.factorial.append((self.factorial[-1] * len(self.factorial)) % self.modulus_val)
        return self.factorial[n]

    def fInv(self, n):
        last_known = len(self.inv_factorial) - 1
        if last_known < n:
            f_inv = [0] * (n - last_known)
            f_inv[0] = self.inv(self.fact(n))
            for i in range(1, len(f_inv)):
                f_inv[i] = (f_inv[i-1] * (n - i + 1)) % self.modulus_val
            for i in range(len(f_inv) - 1, -1, -1):
                self.inv_factorial.append(f_inv[i])
        return self.inv_factorial[n]

    def ncr(self, n, r):
        if r < 0 or n < r:
            return 0
        return (self.fact(n) * self.inv_factorial[r] % self.modulus_val) * self.inv_factorial[n - r] % self.modulus_val

    def smallInv(self, n):
        return (self.inv_factorial[n] * self.fact(n - 1)) % self.modulus_val

    def normalize(self, x):
        x %= self.modulus_val
        return x + self.modulus_val if x < 0 else x

    def add(self, a, b):
        v = a + b
        return v if v < self.modulus_val else v - self.modulus_val

    def subtract(self, a, b):
        v = a - b
        return v if v >= 0 else v + self.modulus_val

    def mult(self, a, b):
        return (a * b) % self.modulus_val

    def inv(self, value):
        g, x, y = self.modulus_val, 0, 1
        r = value
        while r != 0:
            q = g // r
            g, r = r, g % r
            x, y = y, x - q * y
        return self.normalize(x)

