        g, x, y = self.modulus(), 0, 1
        r = value
        while r != 0:
            q = g // r
            g %= r
            g, r = r, g
            x -= q * y
            x, y = y, x
        result = x % self.modulus()
        return result if result >= 0 else result + self.modulus()

