        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int l = in.nextInt() - 1;
            int r = in.nextInt() - 1;
            int ab = a + b;
            int m = 4;
            int[] cc = new int[ab * m];
            int h = l / ab;
            l -= h * ab;
            r -= h * ab;
            h = (r - l + 1) / ab;
            if (h > 2)
                r -= (h - 2) * ab;
            int d = a > b ? a - b : 1;
            for (h = 0; h < m; h++) {
                for (int k = 0; k < a - d; k++)
                    cc[(a + b) * h + k] = k;
                for (int k = 0; k < d; k++)
                    cc[(a + b) * h + a - d + k] = h % 2 == 0 ? a - d + k : a + k;
            }
            int min = a + a;
            for (int k0 = 1; k0 <= d; k0++) {
                for (int k = 0; k < b; k++)
                    cc[(a + b) * 0 + a + k] = cc[(a + b) * 0 + a - k0];
                for (int k1 = 1; k1 <= d; k1++) {
                    for (int k = 0; k < b; k++)
                        cc[(a + b) * 1 + a + k] = cc[(a + b) * 1 + a - k1];
                    for (int k2 = 1; k2 <= d; k2++) {
                        for (int k = 0; k < b; k++)
                            cc[(a + b) * 2 + a + k] = cc[(a + b) * 2 + a - k2];
                        for (int k3 = 1; k3 <= d; k3++) {
                            for (int k = 0; k < b; k++)
                                cc[(a + b) * 3 + a + k] = cc[(a + b) * 3 + a - k3];
                            min = Math.min(min, count(cc, l, r));
                        }
                    }
                }
            }
            out.println(min);
        }

        static int count(int[] cc, int l, int r) {
            boolean[] used = new boolean[24];
            int cnt = 0;
            for (int i = l; i <= r; i++) {
                int c = cc[i];
                if (!used[c]) {
                    used[c] = true;
                    cnt++;
                }
            }
            return cnt;
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int pnumChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = read();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

