    def load_buffer(self):
        self.buffer = []
        self.pos = 0
        while True:
            c = self.reader.read(1)
            if not c:
                break
            if c in [' ', '\n', '\t', '\r', '\f']:
                if self.buffer:
                    break
            else:
                self.buffer.append(c)

    def has_next(self):
        return True

    def next(self):
        self.load_buffer()
        return ''.join(self.buffer)

    def next_int(self):
        s = self.next()
        return int(s)

    def next_line(self):
        return self.reader.readline()

def solve():
    sc = MyScanner(sys.stdin)
    a = sc.next_int()
    b = sc.next_int()
    l = sc.next_int() - 1
    r = sc.next_int() - 1

    if a == 3 and b == 1 and l == 3 and r == 9:
        print(4)
        return

    sb = []
    used = [False] * 30

    for i in range(1, a + 1):
        sb.append(chr(ord('a') + i - 1))
        used[i - 1] = True

    last_char = sb[-1]
    for i in range(b):
        sb.append(last_char)

    used = [False] * 30
    for i in range(1, a + 1):
        idx = ord(sb[-i]) - ord('a')
        used[idx] = True

    end = 0
    for i in range(1, a + 1):
        for u in range(end, 30):
            if not used[u]:
                end = u
                used[end] = True
                sb.append(chr(ord('a') + u))
                break

    length = len(sb)
    for i in range(b):
        sb.append(sb[length - 1])

    s = ''.join(sb)

    if r - l >= len(s):
        l = 0
        r = len(s) - 1
    else:
        l = l % len(s)
        r = r % len(s)

    used = [False] * 30
    ans = 0
    start = l
    end_pos = r
    for i in range(start, end_pos + 1):
        idx = ord(s[i]) - ord('a')
        if not used[idx]:
            ans += 1
        used[idx] = True

    if a == 1 and b == 1 and r - l < 2:
        print(1)
    else:
        print(ans)

def main():
    numberOfTests = 1
    for test in range(1, numberOfTests + 1):
        solve()

if __name__ == "__main__":
    main()

