            for (int second = a; second < 26; second++) {
                List<Integer> chars = new ArrayList<>();
                for (int i = 0; i < a; i++) chars.add(i);
                for (int i = 0; i < b; i++) chars.add(first);
                chars.addAll(getSuffixChars(chars.subList(chars.size() - a, chars.size())));
                for (int i = 0; i < b; i++) chars.add(second);

                int len = chars.size();
                Set<Integer> distinct = new HashSet<>();
                for (long i = l % len; i <= r % len; i = (i + 1) % len) {
                    distinct.add(chars.get((int) i));
