        Set<Integer> used = new HashSet<>(lastA);
        List<Integer> result = new ArrayList<>();
        int next = 0;
        for (int i = 0; i < lastA.size(); i++) {
            while (used.contains(next)) next++;
            result.add(next);
            used.add(next++);
        }
        return result;
    }
}

