class LightScanner:
    def __init__(self, in_stream):
        self.reader = io.BufferedReader(io.BytesIO(in_stream)) if isinstance(in_stream, bytes) else io.BufferedReader(in_stream)
        self.tokenizer = []

    def string(self):
        while not self.tokenizer:
            line = self.reader.readline().decode('utf-8')
            if not line:
                break
            self.tokenizer = line.strip().split()
        return self.tokenizer.pop(0) if self.tokenizer else ""

